# 증권사 리포트·주가 전망·투자의견 관련 기사 제외
BLOCKED_STOCK_KEYWORDS = {
    # 증권/주가 관련 표현 자체는 더 이상 광범위하게 차단하지 않습니다.
    # 아래처럼 원전·건설 사업과 무관한 순수 주식 추천/매매성 표현만 차단합니다.
    "오늘의 추천주",
    "추천 종목",
    "급등주 추천",
    "상한가 종목",
    "단타",
    "매수 추천",
    "매도 추천",
    "주식 투자 추천",
    "종목 추천",
    "테마주 추천",
    "stock pick",
    "stocks to buy",
    "buy now",
    "trading signal",
}



EXCLUDED_PUBLISHERS = {
    "SMR Intel",
    "Nuclear Newswire",
    "NuclearNewswire",
    "Nuclear Newswire (ANS)",
    "ANS Nuclear Newswire",
    "American Nuclear Society",  # ans.org/news = Nuclear Newswire
    "NRC News",
    "NRC",
    "U.S. NRC",
    "US NRC",
    "Nuclear Regulatory Commission",
}

# 출처 URL에 아래 문자열이 있으면 표시/수집에서 제외합니다.
EXCLUDED_HOST_KEYWORDS = {
    "nrc.gov",
    "ans.org/news",
    "nuclearnewswire",
}



def _nuclear_movie_event_key(article: Article) -> str | None:
    """
    같은 날짜의 한수원/원전/원자력/원자력본부 + 영화 관련 보도는
    띄어쓰기·표현 차이와 관계없이 동일 이슈로 묶습니다.
    """
    haystack = normalized(f"{article.title} {article.description}")
    compact = re.sub(r"\s+", "", haystack)

    nuclear_terms = (
        "원자력",
        "원전",
        "한국수력원자력",
        "한수원",
        "원자력본부",
        "원전본부",
        "nuclear",
        "khnp",
    )
    movie_terms = (
        "영화",
        "영화상영",
        "무료영화",
        "영화관람",
        "무비",
        "movie",
        "moviescreening",
        "filmscreening",
    )

    has_nuclear = any(term.replace(" ", "") in compact for term in nuclear_terms)
    has_movie = any(term.replace(" ", "") in compact for term in movie_terms)

    if not (has_nuclear and has_movie):
        return None

    return article.published.astimezone(KST).strftime("%Y-%m-%d")


def is_excluded_source(
    publisher: str = "",
    link: str = "",
    source_url: str = "",
) -> bool:
    """NRC / Nuclear Newswire 등 제외 매체를 출판사명·URL로 판정합니다."""
    pub = (publisher or "").strip().lower()
    # 과거 archive/state에 NucNet 태그 목록 URL이 남아 있어도 표시하지 않습니다.
    if pub == "nucnet" and "/news/tagged/" in (link or "").lower():
        return True
    pub_compact = pub.replace(" ", "").replace("-", "")
    excluded_names = {name.lower() for name in EXCLUDED_PUBLISHERS}
    if pub in excluded_names:
        return True
    if "nrc news" in pub:
        return True
    # NuclearNewswire / Nuclear Newswire 표기 변형
    if "nuclearnewswire" in pub_compact:
        return True

    haystack = f"{link} {source_url}".lower()
    return any(host in haystack for host in EXCLUDED_HOST_KEYWORDS)

@dataclass
class Article:
    title: str
    link: str
    published: datetime
    language: str
    group: str
    publisher: str
    image: str
    source_url: str
    description: str = ""


def _report_window_for_date(report_date) -> tuple[datetime, datetime]:
    """
    보고일 기준 기사 구간을 반환합니다.

    - 화~일요일: 전일 06:00 ~ 당일 06:00
    - 월요일: 금요일 06:00 ~ 월요일 06:00

    따라서 토요일과 일요일도 각각 독립적인 하루 보고일로 유지하고,
    월요일에만 주말 전체를 다시 포함합니다.
    """
    end = datetime(
        report_date.year,
        report_date.month,
        report_date.day,
        6, 0, 0,
        tzinfo=KST,
    )
    if report_date.weekday() == 0:  # Monday
        start = end - timedelta(days=3)
    else:
        start = end - timedelta(days=1)
    return start, end


def period(now: datetime) -> tuple[datetime, datetime]:
    """
    KST 달력 날짜를 기준으로 현재 '금일' 보고구간을 반환합니다.
    전일/금일/익일 표시는 날짜가 바뀌는 00:00에 자동 전환되며,
    기사 구간의 경계시각은 항상 06:00입니다.

    예)
    토요일 금일 = 금요일 06:00 ~ 토요일 06:00
    일요일 금일 = 토요일 06:00 ~ 일요일 06:00
    월요일 금일 = 금요일 06:00 ~ 월요일 06:00
    화요일 금일 = 월요일 06:00 ~ 화요일 06:00
    """
    report_date = now.astimezone(KST).date()
    return _report_window_for_date(report_date)


def _previous_report_boundary(boundary: datetime) -> datetime:
    """직전 달력일의 06:00 기준시각을 반환합니다. 주말도 건너뛰지 않습니다."""
    return boundary - timedelta(days=1)


def _next_report_boundary(boundary: datetime) -> datetime:
    """다음 달력일의 06:00 기준시각을 반환합니다. 주말도 건너뛰지 않습니다."""
    return boundary + timedelta(days=1)


def brief_periods(now: datetime) -> dict[str, tuple[datetime, datetime]]:
    """
    KST 달력일 기준으로 전일·금일·익일 보고구간을 계산합니다.
    각 탭은 해당 '보고일'의 규칙을 독립적으로 적용합니다.

    예) 일요일:
      전일(토) = 금요일 06:00 ~ 토요일 06:00
      금일(일) = 토요일 06:00 ~ 일요일 06:00
      익일(월) = 금요일 06:00 ~ 월요일 06:00

    예) 월요일:
      전일(일) = 토요일 06:00 ~ 일요일 06:00
      금일(월) = 금요일 06:00 ~ 월요일 06:00
      익일(화) = 월요일 06:00 ~ 화요일 06:00
    """
    today = now.astimezone(KST).date()
    return {
        "전일": _report_window_for_date(today - timedelta(days=1)),
        "금일": _report_window_for_date(today),
        "익일": _report_window_for_date(today + timedelta(days=1)),
    }


def split_title_and_publisher(raw_title: str) -> tuple[str, str]:
    raw_title = html.unescape(raw_title or "").strip()
    match = re.match(r"^(.*)\s+-\s+([^-]{2,100})$", raw_title)
    if match:
        return match.group(1).strip(), match.group(2).strip()
    return raw_title, ""


def extract_image(entry) -> str:
    """
    RSS 단계에서 대표 이미지를 최대한 확보합니다.
    우선순위:
    1) media:content / media:thumbnail
    2) enclosure
    3) RSS link의 image enclosure
    4) content/summary/description 내부 img(src, data-src, srcset)
    """

    # 1. Media RSS
    for field in ("media_content", "media_thumbnail"):
        values = getattr(entry, field, None)
        if not values:
            continue
        for value in values:
            if not isinstance(value, dict):
                continue
            url = (
                value.get("url")
                or value.get("href")
                or value.get("src")
                or ""
            ).strip()
            if url:
                return html.unescape(url)

    # 2. RSS enclosure
    enclosures = getattr(entry, "enclosures", None) or []
    for enclosure in enclosures:
        if not isinstance(enclosure, dict):
            continue
        content_type = str(
            enclosure.get("type")
            or enclosure.get("medium")
            or ""
        ).lower()
        url = (
            enclosure.get("href")
            or enclosure.get("url")
            or ""
        ).strip()
        if url and (
            content_type.startswith("image/")
            or content_type == "image"
            or re.search(r"\.(?:jpe?g|png|webp|gif)(?:\?|$)", url, re.I)
        ):
            return html.unescape(url)

    # 3. feedparser가 links 배열로 제공하는 enclosure
    for link_info in getattr(entry, "links", None) or []:
        if not isinstance(link_info, dict):
            continue
        rel = str(link_info.get("rel", "")).lower()
        content_type = str(link_info.get("type", "")).lower()
        href = str(link_info.get("href", "")).strip()
        if not href:
            continue
        if (
            rel == "enclosure"
            and (
                content_type.startswith("image/")
                or re.search(r"\.(?:jpe?g|png|webp|gif)(?:\?|$)", href, re.I)
            )
        ):
            return html.unescape(href)

    # 4. RSS content / summary / description HTML 내부 이미지
    html_candidates: list[str] = []

    content_values = getattr(entry, "content", None) or []
    for content in content_values:
        if isinstance(content, dict):
            value = content.get("value", "")
            if value:
                html_candidates.append(str(value))

    summary = (
        getattr(entry, "summary", "")
        or getattr(entry, "description", "")
        or ""
    )
    if summary:
        html_candidates.append(str(summary))

    for raw_html in html_candidates:
        match = re.search(
            r'<img[^>]+(?:src|data-src|data-original|data-lazy-src)\s*=\s*["\']([^"\']+)["\']',
            raw_html,
            re.I,
        )
        if match:
            return html.unescape(match.group(1).strip())

        srcset_match = re.search(
            r'<img[^>]+srcset\s*=\s*["\']([^"\']+)["\']',
            raw_html,
            re.I,
        )
        if srcset_match:
            candidates = []
            for part in srcset_match.group(1).split(","):
                url = part.strip().split()[0] if part.strip() else ""
                if url:
                    candidates.append(url)
            if candidates:
                return html.unescape(candidates[-1])

    return ""


def clean_description(raw: str, title: str = "", publisher: str = "") -> str:
    """RSS/HTML에서 가져온 설명을 카드용 짧은 문장으로 정리합니다."""
    if not raw:
        return ""

    cleaned = re.sub(r"<[^>]+>", " ", raw)
    cleaned = html.unescape(cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()

    if not cleaned:
        return ""

    # RSS summary가 단순히 '기사제목 + 언론사'만 반복하는 경우 제외
    normalized_cleaned = normalized(cleaned)
    normalized_title = normalized(title)
    normalized_publisher = normalized(publisher)

    if normalized_title and normalized_title in normalized_cleaned:
        remainder = normalized_cleaned.replace(normalized_title, " ", 1).strip()
        if not remainder or remainder == normalized_publisher:
            return ""

    # 너무 짧은 문자열은 기사 미리보기로 사용하지 않음
    if len(cleaned) < 20:
        return ""

    # 카드에는 과도하게 긴 문장이 필요하지 않음
    return cleaned[:320].rstrip()


class _MetaTagParser(HTMLParser):
    """원문 HTML에서 메타정보, 대표 이미지 후보, 본문 문단 후보를 추출합니다."""

    def __init__(self, base_url: str = ""):
        super().__init__(convert_charrefs=True)
        self.values: dict[str, str] = {}
        self.base_url = base_url
        self.image_candidates: list[tuple[int, str]] = []
        self.jsonld_image_candidates: list[str] = []
        self.paragraphs: list[str] = []
        self._in_p = False
        self._p_chunks: list[str] = []

    def handle_starttag(self, tag: str, attrs):
        attr_map = {
            str(key).lower(): str(value)
            for key, value in attrs
            if key and value is not None
        }

        if tag.lower() == "meta":
            key = (
                attr_map.get("property")
                or attr_map.get("name")
                or attr_map.get("itemprop")
                or ""
            ).lower()
            content = attr_map.get("content", "").strip()
            if key and content and key not in self.values:
                self.values[key] = content
            return

        if tag.lower() in ("img", "source"):
            src = (
                attr_map.get("src")
                or attr_map.get("data-src")
                or attr_map.get("data-original")
                or attr_map.get("data-lazy-src")
                or ""
            ).strip()

            srcset = attr_map.get("srcset", "").strip()
            if not src and srcset:
                srcset_items = []
                for part in srcset.split(","):
                    token = part.strip()
                    if not token:
                        continue
                    src_url = token.split()[0]
                    descriptor = token.split()[1] if len(token.split()) > 1 else ""
                    score_hint = 0
                    match = re.search(r"(\d+)(w|x)", descriptor)
                    if match:
                        score_hint = int(match.group(1))
                    srcset_items.append((score_hint, src_url))
                if srcset_items:
                    srcset_items.sort(key=lambda item: item[0], reverse=True)
                    src = srcset_items[0][1]

            if not src:
                return

            src_lower = src.lower()
            blocked = (
                "logo", "icon", "sprite", "avatar", "profile", "banner",
                "advert", "ads.", "tracking", "pixel", "favicon",
            )
            if any(token in src_lower for token in blocked):
                return

            try:
                width = int(re.sub(r"[^0-9]", "", attr_map.get("width", "")) or "0")
            except Exception:
                width = 0
            try:
                height = int(re.sub(r"[^0-9]", "", attr_map.get("height", "")) or "0")
            except Exception:
                height = 0

            class_text = f"{attr_map.get('class', '')} {attr_map.get('id', '')} {attr_map.get('itemprop', '')}".lower()
            score = width * height
            if tag.lower() == "source":
                score += 100_000
            if any(word in class_text for word in ("article", "news", "content", "photo", "image", "thumb", "figure", "lead", "main")):
                score += 500_000

            self.image_candidates.append((score, urljoin(self.base_url, src)))
            return

        if tag.lower() == "p":
            self._in_p = True
            self._p_chunks = []

    def handle_endtag(self, tag: str):
        if tag.lower() == "p" and self._in_p:
            paragraph = re.sub(r"\s+", " ", " ".join(self._p_chunks)).strip()
            if paragraph:
                self.paragraphs.append(paragraph)
            self._in_p = False
            self._p_chunks = []

    def handle_data(self, data: str):
        if self._in_p and data.strip():
            self._p_chunks.append(data.strip())



def _extract_jsonld_image_candidates(decoded_html: str, base_url: str) -> list[str]:
    """
    기사 페이지 JSON-LD에 들어있는 image 필드를 별도로 추출합니다.
    미리보기(description)와 무관하게 대표 이미지가 있는 경우가 많아
    썸네일 확보율을 높이는 데 사용합니다.
    """
    results: list[str] = []

    def add_candidate(value):
        if not value:
            return
        if isinstance(value, str):
            results.append(urljoin(base_url, value.strip()))
            return
        if isinstance(value, list):
            for item in value:
                add_candidate(item)
            return
        if isinstance(value, dict):
            for key in ("url", "contentUrl", "thumbnailUrl"):
                if value.get(key):
                    results.append(urljoin(base_url, str(value[key]).strip()))
            if value.get("image"):
                add_candidate(value.get("image"))

    for match in re.finditer(
        r'<script[^>]+type=["\\\']application/ld\\+json["\\\'][^>]*>(.*?)</script>',
        decoded_html,
        re.I | re.S,
    ):
        raw_json = html.unescape(match.group(1)).strip()
        if not raw_json:
            continue
        try:
            payload = json.loads(raw_json)
        except Exception:
            continue

        items = payload if isinstance(payload, list) else [payload]
        for item in items:
            if not isinstance(item, dict):
                continue
            if item.get("@graph") and isinstance(item["@graph"], list):
                graph_items = [x for x in item["@graph"] if isinstance(x, dict)]
            else:
                graph_items = [item]

            for graph_item in graph_items:
                add_candidate(graph_item.get("image"))

    # 중복 제거
    unique: list[str] = []
    seen = set()
    for url in results:
        normalized = url.strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        unique.append(normalized)
    return unique


def _best_jsonld_image_candidate(candidates: list[str]) -> str:
    blocked = ("logo", "icon", "sprite", "avatar", "profile", "banner", "pixel", "favicon")
    for candidate in candidates:
        lower = candidate.lower()
        if any(token in lower for token in blocked):
            continue
        return candidate
    return ""



def _best_html_image_candidate(parser: _MetaTagParser) -> str:
    if not parser.image_candidates:
        return ""
    parser.image_candidates.sort(key=lambda item: item[0], reverse=True)
    return parser.image_candidates[0][1]


def _best_paragraph_description(
    parser: _MetaTagParser,
    title: str,
    publisher: str,
) -> str:
    """
    메타 description이 없을 때 본문 첫 문단 중 기사다운 문장을 선택합니다.
    메뉴/저작권/기자정보 같은 짧은 문장은 제외합니다.
    """
    blocked_terms = (
        "무단전재", "재배포", "저작권", "기자", "입력", "수정",
        "구독", "로그인", "copyright", "all rights reserved",
    )
    for paragraph in parser.paragraphs[:30]:
        cleaned = clean_description(paragraph, title, publisher)
        if not cleaned:
            continue
        lower = cleaned.lower()
        if any(term in lower for term in blocked_terms):
            continue
        if len(cleaned) >= 35:
            return cleaned
    return ""


def _fetch_article_metadata(article: Article) -> tuple[str, str]:
    """
    RSS에 이미지/설명이 부족한 경우 원문 페이지 메타태그에서 보완합니다.
    원문 접근 실패는 빈 값으로 처리하여 전체 수집을 중단하지 않습니다.
    """
    if article.image and article.description:
        return article.image, article.description


    try:
        request = Request(
            article.link,
            headers={
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/131.0 Safari/537.36"
                ),
                "Accept-Language": "ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7",
            },
        )
        with urlopen(request, timeout=ARTICLE_META_TIMEOUT_SECONDS) as response:
            final_url = response.geturl()
            payload = response.read(ARTICLE_META_MAX_BYTES)

        # 검색 중간 페이지 등 원문이 아닌 호스트에서는 잘못된 대표이미지를 쓰지 않습니다.
        final_host = urlparse(final_url).netloc.lower()
        if not final_host:
            return article.image, article.description

        decoded = payload.decode("utf-8", errors="ignore")
        parser = _MetaTagParser(final_url)
        parser.feed(decoded)
        parser.jsonld_image_candidates = _extract_jsonld_image_candidates(decoded, final_url)

        image = article.image
        if not image:
            image = (
                parser.values.get("og:image")
                or parser.values.get("twitter:image")
                or parser.values.get("twitter:image:src")
                or parser.values.get("image")
                or _best_jsonld_image_candidate(parser.jsonld_image_candidates)
                or _best_html_image_candidate(parser)
                or ""
            ).strip()
            if image:
                image = urljoin(final_url, image)

        description = article.description
        if not description:
            raw_description = (
                parser.values.get("og:description")
                or parser.values.get("twitter:description")
                or parser.values.get("description")
                or ""
            )
            description = clean_description(
                raw_description,
                article.title,
                article.publisher,
            )

        # 메타 설명이 없으면 실제 본문 첫 문단에서 보완
        if not description:
            description = _best_paragraph_description(
                parser,
                article.title,
                article.publisher,
            )

        return image, description
    except Exception:
        return article.image, article.description



def _image_extension(content_type: str, url: str) -> str:
    content_type = (content_type or "").split(";", 1)[0].strip().lower()
    mapping = {
        "image/jpeg": ".jpg",
        "image/jpg": ".jpg",
        "image/png": ".png",
        "image/webp": ".webp",
        "image/gif": ".gif",
    }
    if content_type in mapping:
        return mapping[content_type]

    suffix = Path(urlparse(url).path).suffix.lower()
    if suffix in {".jpg", ".jpeg", ".png", ".webp", ".gif"}:
        return ".jpg" if suffix == ".jpeg" else suffix
    return ".jpg"


def _load_thumbnail_fingerprint_store() -> dict[str, dict]:
    if not THUMBNAIL_FINGERPRINT_FILE.exists():
        return {}
    try:
        data = json.loads(
            THUMBNAIL_FINGERPRINT_FILE.read_text(encoding="utf-8")
        )
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_thumbnail_fingerprint_store(store: dict[str, dict]) -> None:
    try:
        THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)
        THUMBNAIL_FINGERPRINT_FILE.write_text(
            json.dumps(store, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
    except Exception:
        pass


def _compute_thumbnail_fingerprint(path: Path) -> dict[str, object]:
    """
    이미지 파일 자체의 fingerprint를 만듭니다.

    sha256:
      파일 바이트가 완전히 같은 사진 검출.

    dhash:
      Pillow가 설치되어 있으면 64-bit difference hash를 추가 생성.
      언론사가 같은 사진을 리사이즈/재압축해도 거의 같은 값을 만들기 위한 값입니다.
      Pillow가 없는 환경에서는 sha256만 사용하며 전체 수집은 중단하지 않습니다.
    """
    try:
        payload = path.read_bytes()
    except Exception:
        return {}

    if not payload:
        return {}

    result: dict[str, object] = {
        "sha256": hashlib.sha256(payload).hexdigest(),
        "size_bytes": len(payload),
    }

    try:
        from PIL import Image  # type: ignore

        with Image.open(path) as image:
            width, height = image.size
            result["width"] = int(width)
            result["height"] = int(height)

            # 같은 사진의 리사이즈/재압축을 잡기 위한 grayscale perceptual hashes
            gray_d = image.convert("L").resize((9, 8))
            pixels_d = list(gray_d.getdata())

            gray_a = image.convert("L").resize((8, 8))
            pixels_a = list(gray_a.getdata())

        bits = 0
        bit_index = 0
        for row in range(8):
            base = row * 9
            for col in range(8):
                bits |= (1 if pixels_d[base + col] > pixels_d[base + col + 1] else 0) << bit_index
                bit_index += 1
        result["dhash"] = f"{bits:016x}"

        avg = sum(pixels_a) / max(1, len(pixels_a))
        abits = 0
        for bit_index, value in enumerate(pixels_a):
            abits |= (1 if value >= avg else 0) << bit_index
        result["ahash"] = f"{abits:016x}"
    except Exception:
        # Pillow 미설치/손상 이미지라도 정확 파일 해시(SHA-256)는 계속 사용합니다.
        pass

    return result


def _register_thumbnail_fingerprint(
    local_path: str,
    source_url: str,
    store: dict[str, dict],
) -> None:
    if not local_path:
        return

    path = Path(local_path)
    if not path.exists() or not path.is_file():
        return

    name = path.name.lower()
    record = store.get(name, {})
    if not isinstance(record, dict):
        record = {}

    # 파일이 바뀌었거나 fingerprint가 없으면 다시 계산
    try:
        current_size = path.stat().st_size
    except Exception:
        current_size = 0

    if (
        not record.get("sha256")
        or int(record.get("size_bytes") or 0) != current_size
    ):
        computed = _compute_thumbnail_fingerprint(path)
        if computed:
            record.update(computed)

    parsed = urlparse(source_url or "")
    original_name = Path(parsed.path).name if parsed.path else ""

    urls = record.get("source_urls")
    if not isinstance(urls, list):
        urls = []
    if source_url and source_url not in urls:
        urls.append(source_url)
        # sidecar 파일이 너무 커지지 않도록 최근 URL 일부만 유지
        urls = urls[-8:]

    record["source_urls"] = urls
    if original_name:
        record["original_filename"] = original_name

    store[name] = record


def _download_thumbnail(image_url: str) -> str:
    if not image_url:
        return ""
    if image_url.startswith("assets/thumbnails/"):
        return image_url

    THUMBNAIL_DIR.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha1(
        image_url.encode("utf-8", errors="ignore")
    ).hexdigest()[:24]

    for ext in (".jpg", ".png", ".webp", ".gif"):
        existing = THUMBNAIL_DIR / f"{digest}{ext}"
        if existing.exists() and existing.stat().st_size > 0:
            return existing.as_posix()

    try:
        parsed = urlparse(image_url)
        referer = (
            f"{parsed.scheme}://{parsed.netloc}/"
            if parsed.scheme and parsed.netloc
            else image_url
        )
        request = Request(
            image_url,
            headers={
                "User-Agent": (
                    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                    "AppleWebKit/537.36 (KHTML, like Gecko) "
                    "Chrome/131.0 Safari/537.36"
                ),
                "Referer": referer,
                "Accept": "image/avif,image/webp,image/apng,image/*,*/*;q=0.8",
            },
        )
        with urlopen(request, timeout=THUMBNAIL_TIMEOUT_SECONDS) as response:
            content_type = response.headers.get("Content-Type", "")
            if not content_type.lower().startswith("image/"):
                return ""
            payload = response.read(THUMBNAIL_MAX_BYTES + 1)

        if not payload or len(payload) > THUMBNAIL_MAX_BYTES:
            return ""

        ext = _image_extension(content_type, image_url)
        target = THUMBNAIL_DIR / f"{digest}{ext}"
        target.write_bytes(payload)
        return target.as_posix()
    except Exception:
        return ""


def cache_article_thumbnails(
    articles_by_period: dict[str, list[Article]],
) -> None:
    """
    표시될 기사 이미지를 로컬 저장하고 이미지 fingerprint도 함께 생성합니다.

    저장 정보:
    - 원본 이미지 URL
    - 원본 URL의 파일명
    - SHA-256
    - 이미지 width / height (Pillow 사용 가능 시)
    - dHash (Pillow 사용 가능 시)
    """
    by_image_url: dict[str, list[Article]] = {}

    for articles in articles_by_period.values():
        for article in articles:
            if article.image:
                by_image_url.setdefault(article.image, []).append(article)

    if not by_image_url:
        return

    fingerprint_store = _load_thumbnail_fingerprint_store()
    workers = min(THUMBNAIL_DOWNLOAD_WORKERS, len(by_image_url))

    with ThreadPoolExecutor(max_workers=workers) as executor:
        future_map = {
            executor.submit(_download_thumbnail, image_url): image_url
            for image_url in by_image_url
        }

        for future in as_completed(future_map):
            original_url = future_map[future]
            try:
                local_path = future.result()
            except Exception:
                continue
            if not local_path:
                continue

            _register_thumbnail_fingerprint(
                local_path,
                original_url,
                fingerprint_store,
            )

            for article in by_image_url.get(original_url, []):
                article.image = local_path

    _save_thumbnail_fingerprint_store(fingerprint_store)

    exact_count = sum(
        1 for value in fingerprint_store.values()
        if isinstance(value, dict) and value.get("sha256")
    )
    perceptual_count = sum(
        1 for value in fingerprint_store.values()
        if isinstance(value, dict) and value.get("dhash")
    )
    if exact_count:
        print(
            f"[THUMBNAIL FINGERPRINT] exact_sha256={exact_count} "
            f"/ perceptual_dhash={perceptual_count}"
        )
        if perceptual_count == 0:
            print(
                "[THUMBNAIL FINGERPRINT] Pillow unavailable or images undecodable; "
                "SHA-256 exact-image matching remains active."
            )

def cleanup_old_thumbnails(now: datetime) -> None:
    if not THUMBNAIL_DIR.exists():
        return

    cutoff = now.timestamp() - THUMBNAIL_KEEP_DAYS * 24 * 60 * 60
    for path in THUMBNAIL_DIR.iterdir():
        if not path.is_file():
            continue
        try:
            if path.stat().st_mtime < cutoff:
                path.unlink()
        except Exception:
            continue


def enrich_article_metadata(articles_by_period: dict[str, list[Article]]) -> None:
    """
    전일/금일/익일에서 최종 표시될 기사만 대상으로 대표 이미지와 설명을 보완합니다.
    동일 URL은 한 번만 조회하고, 원문 접근은 ThreadPool로 병렬 처리합니다.
    """
    started = time.monotonic()
    articles_by_url: dict[str, list[Article]] = {}

    for articles in articles_by_period.values():
        for article in articles:
            articles_by_url.setdefault(article.link, []).append(article)

    targets = [
        items[0]
        for items in articles_by_url.values()
        if not (items[0].image and items[0].description)
    ]

    if not targets:
        print("[META ENRICH] targets=0 / elapsed=0.0s")
        return

    workers = min(ARTICLE_META_WORKERS, len(targets))

    with ThreadPoolExecutor(max_workers=workers) as executor:
        future_map = {
            executor.submit(_fetch_article_metadata, article): article.link
            for article in targets
        }

        for future in as_completed(future_map):
            original_key = future_map[future]
            try:
                image, description = future.result()
            except Exception:
                continue

            for article in articles_by_url.get(original_key, []):
                representative = articles_by_url[original_key][0]
                if representative.link and representative.link != original_key:
                    article.link = representative.link

                if image and not article.image:
                    article.image = image
                if description and not article.description:
                    article.description = description

    elapsed = time.monotonic() - started
    filled_images = sum(
        1
        for items in articles_by_period.values()
        for article in items
        if (article.image or "").strip()
    )
    filled_descriptions = sum(
        1
        for items in articles_by_period.values()
        for article in items
        if (article.description or "").strip()
    )

    print(
        f"[META ENRICH] targets={len(targets)} "
        f"/ workers={workers} "
        f"/ images={filled_images} "
        f"/ descriptions={filled_descriptions} "
        f"/ elapsed={elapsed:.1f}s"
    )


HYUNDAI_VOLLEYBALL_TERMS = {
    # 종목/리그 직접 표현
    "배구", "여자배구", "프로배구", "v리그", "v-리그",
    "volleyball", "v-league", "v league", "배구단",

    # 현대건설 배구단 관련 인물/경기 문맥
    "김연경", "신인감독", "격돌", "맞대결",
    "세트", "득점", "리시브", "블로킹", "스파이크",
    "코트", "홈경기", "원정경기",
}


def is_hyundai_volleyball_article(title: str, summary: str = "") -> bool:
    """현대건설 힐스테이트 배구단 관련 기사를 회사 뉴스에서 제외합니다."""
    haystack = html.unescape(f"{title} {summary}").lower()

    # 명확한 배구 단서가 하나라도 있으면 제외
    if any(term in haystack for term in HYUNDAI_VOLLEYBALL_TERMS):
        return True

    # '감독/선수/경기/승리/패배'는 일반 기사에도 나올 수 있으므로
    # 스포츠 문맥 단서가 2개 이상 함께 있을 때만 제외
    weak_terms = {"감독", "선수", "선수단", "경기", "승리", "패배"}
    weak_hits = sum(1 for term in weak_terms if term in haystack)
    return weak_hits >= 2


def normalized(title: str) -> str:
    return " ".join(re.sub(r"[^0-9a-z가-힣]+", " ", title.lower()).split())


