def _has_executive_activity(title: str, summary: str = "") -> bool:
    hay = html.unescape(f"{title} {summary}").lower()
    return any(term in hay for term in EXECUTIVE_ACTIVITY_TERMS)


def classify_executive_activity_group(title: str, summary: str = "") -> str | None:
    """
    대표이사/사장/CEO 등 핵심 경영진의 주요 활동 기사를 회사 탭으로 분류합니다.

    원칙:
    - 회사명/기관명 + 핵심 직함이 기사에 연결되어 있어야 함
    - 취임/면담/협력/현장점검/수주/경영활동 등 주요 활동은 유지
    - 회사명 없이 인물명만 있는 경우는 동명이인 오탐 방지를 위해 여기서는 강제 분류하지 않음
    """
    title_clean = html.unescape(title or "")
    summary_clean = html.unescape(summary or "")
    hay = f"{title_clean} {summary_clean}".lower()

    if not _has_executive_role(hay):
        return None

    # 현대건설 경영진
    if mentions_hyundai_ec(title_clean, summary_clean):
        return "현대건설"

    # 한수원 경영진
    khnp_terms = (
        "한국수력원자력", "한수원", "khnp",
        "한울원자력본부", "고리원자력본부", "월성원자력본부",
        "새울원자력본부", "한빛원자력본부",
    )
    if any(term in hay for term in khnp_terms):
        return "한국수력원자력"

    # 한국전력 경영진
    kepco_terms = (
        "한국전력공사", "한국전력", "한전", "kepco",
    )
    # 한전MCS/KDN 등 계열사는 본체보다 먼저 구분
    if _mentions_kepco_kdn(title_clean, summary_clean) or _mentions_kepco_mcs(title_clean, summary_clean):
        return "한전 계열사"
    if _mentions_kepco_affiliate(title_clean, summary_clean) and not _mentions_kepco_parent(title_clean, summary_clean):
        return "한전 계열사"
    if any(term in hay for term in kepco_terms):
        return "한국전력"

    # 국내 주요 건설사 경영진
    if mentions_other_construction_company_in_title(title_clean):
        return "타 건설사"

    # 제목에 없더라도 미리보기에서 회사명 + 대표/사장 직함이 연결된 경우 인정
    if any(term.lower() in hay for term in OTHER_CONSTRUCTION_TERMS):
        return "타 건설사"

    return None



OTHER_CONSTRUCTION_TITLE_PRIORITY_ORDER = (
    ("두산에너빌리티", ("두산에너빌리티", "doosan enerbility")),
    ("삼성물산", ("삼성물산", "samsung c&t")),
    ("대우건설", ("대우건설", "daewoo e&c")),
    ("현대엔지니어링", ("현대엔지니어링", "hyundai engineering")),
    ("DL이앤씨", ("dl이앤씨", "dl e&c")),
    ("GS건설", ("gs건설", "gs e&c")),
    ("SK에코플랜트", ("sk에코플랜트", "sk ecoplant")),
    ("포스코이앤씨", ("포스코이앤씨", "posco e&c")),
    ("롯데건설", ("롯데건설", "lotte e&c", "lotte engineering & construction")),
    ("HDC현대산업개발", ("hdc현대산업개발", "현대산업개발", "hdc hyundai development")),
    ("한화 건설부문", ("한화 건설부문", "한화건설", "hanwha construction")),
)


def detect_title_primary_construction_company(title: str) -> str | None:
    """
    기사 제목에 직접 등장하는 국내 건설사 중 핵심 회사를 판정합니다.

    제목 회사명 > 본문/미리보기 회사명 원칙을 최종 분류까지 강제합니다.
    여러 회사가 제목에 있으면 제목에서 먼저 등장한 회사명을 핵심 주체로 봅니다.
    """
    hay = html.unescape(title or "").lower()

    candidates: list[tuple[int, str]] = []

    # 현대건설
    hyundai_terms = (
        "현대건설",
        "hyundai e&c",
        "hyundai engineering & construction",
        "hdec",
    )
    for term in hyundai_terms:
        idx = hay.find(term)
        if idx >= 0:
            # 현대건설기계는 현대건설로 보지 않음
            if term == "현대건설" and "현대건설기계" in hay:
                machine_idx = hay.find("현대건설기계")
                if machine_idx == idx:
                    continue
            candidates.append((idx, "현대건설"))

    # 타 주요 건설사
    for canonical, aliases in OTHER_CONSTRUCTION_TITLE_PRIORITY_ORDER:
        for term in aliases:
            idx = hay.find(term.lower())
            if idx >= 0:
                candidates.append((idx, "타 건설사"))

    if not candidates:
        return None

    candidates.sort(key=lambda x: x[0])
    return candidates[0][1]


def enforce_title_company_group(article: Article) -> Article:
    """
    최종 안전장치:
    제목에 직접 나온 회사가 있으면 기존 group 값을 덮어써 제목 기준으로 고정합니다.
    """
    title_group = detect_title_primary_construction_company(article.title or "")
    if title_group:
        article.group = title_group
    return article


def classify_priority_company_group(group: str, title: str, summary: str) -> str:
    """
    회사/프로젝트 전용 그룹의 최종 우선순위를 적용합니다.

    최우선 원칙:
    - 기사 제목 또는 본문에 현대건설(Hyundai E&C / Hyundai Engineering & Construction / HDEC)이
      포함되면 다른 회사·프로젝트명이 함께 있어도 반드시 '현대건설'로 분류합니다.
    - 예: '현대건설-테라파워 협력' -> 현대건설
    - 예: '현대건설, Holtec SMR-300 사업 참여' -> 현대건설
    - 예: 'Hyundai E&C and Westinghouse...' -> 현대건설

    현대건설이 없는 기사에 대해서만 원전 대미투자, Holtec, TerraPower,
    Fermi America 등 전용 그룹을 적용합니다.
    """
    haystack = html.unescape(f"{title} {summary}").lower()

    # 최우선: 기사 제목에 직접 등장하는 건설사
    title_company_group = detect_title_primary_construction_company(title)
    if title_company_group:
        return title_company_group

    # 대표이사/사장/CEO 등 핵심 경영진의 주요 활동은 해당 회사/기관 탭으로 우선 분류
    executive_group = classify_executive_activity_group(title, summary)
    if executive_group:
        return executive_group

    # 기사 제목에 타 주요 건설사가 직접 나오면 그 회사가 핵심 주체이므로
    # 본문/미리보기에 현대건설이 함께 있어도 '주요 건설사'를 우선합니다.
    if mentions_other_construction_company_in_title(title):
        return "타 건설사"

    # 그 다음 현대건설 (건설기계 오탐 제외)
    if mentions_hyundai_ec(title, summary):
        return "현대건설"

    # 한전KDN / 한전MCS는 회사명 자체에 '한전/KEPCO'가 포함되므로
    # 한국전력 본체로 오인하지 않고 '한전 계열사'를 우선합니다.
    if _mentions_kepco_kdn(title, summary) or _mentions_kepco_mcs(title, summary):
        return "한전 계열사"

    # 그 외에는 한국전력 본체와 계열사가 함께 언급되면 한국전력 탭을 우선
    if _mentions_kepco_parent(title, summary):
        return "한국전력"

    # 계열사만 언급된 경우 한전 계열사 탭
    if _mentions_kepco_affiliate(title, summary):
        return "한전 계열사"

    # 해외 원전 건설/엔지니어링 회사가 명시되고 실제 원전 문맥이 있으면
    # 일반 Nuclear 또는 WEC 기사로 흩어지지 않도록 전용 탭을 우선 적용합니다.
    foreign_nuclear_company_group = _foreign_nuclear_company_group(title, summary)
    if foreign_nuclear_company_group:
        return foreign_nuclear_company_group

    # Westinghouse 회사명이 직접 언급되면 WEC 탭 우선
    # AP1000만 언급된 코즐로두이 프로젝트 기사는 코즐로두이 탭으로 분류 가능
    if _mentions_westinghouse_explicit(title, summary):
        return "Westinghouse"

    # 2순위 이하: 현대건설이 없는 경우에만 적용
    has_nuclear_term = any(
        term in haystack for term in NUCLEAR_US_INVESTMENT_NUCLEAR_TERMS
    )
    has_us_investment_term = any(
        term in haystack for term in NUCLEAR_US_INVESTMENT_TERMS
    )
    if has_nuclear_term and has_us_investment_term:
        return "원전 대미투자"

    if any(term in haystack for term in SHIN_HANUL_TERMS):
        return "원자력"

    if any(term in haystack for term in HOLTEC_TERMS):
        # Holtec 탭은 회사명/모델명뿐 아니라 실제 원전·SMR 문맥까지 확인
        if is_valid_holtec_article(title, summary):
            return "Holtec"

    if any(term in haystack for term in TERRAPOWER_TERMS):
        return "TerraPower"

    if any(term in haystack for term in FERMI_AMERICA_TERMS):
        return "Fermi America"

    if _mentions_international_nuclear_energy_org(title, summary):
        return "국제 원자력·에너지기구"

    association_group = _nuclear_association_society_group(title, summary)
    if association_group:
        return association_group

    # 현대건설/WEC 등 회사 우선 분류에 걸리지 않은 프로젝트 기사만 코즐로두이 탭
    if _mentions_kozloduy_project(title, summary):
        return "불가리아 코즐로두이 원전"

    return group


def classify_construction_group(group: str, title: str, summary: str) -> str | None:
    """
    건설사 분류 기준:
    - 현대건설: 당사 관련 기사이므로 항상 현대건설 항목에 유지
    - 타 건설사: 원전 관련성 필터를 해제하고 일반 기사까지 모두 유지
    """
    if group != "타 건설사":
        return group

    haystack = html.unescape(f"{title} {summary}").lower()

    # 제목에 타 건설사명이 직접 나오면 '주요 건설사'로 고정합니다.
    if mentions_other_construction_company_in_title(title):
        return "타 건설사"

    # 제목에는 타 건설사가 없고 현대건설이 핵심으로 잡힌 경우만 현대건설로 재분류합니다.
    if mentions_hyundai_ec(title, summary):
        return "현대건설"

    # 타 건설사명/영문명이 본문/미리보기에 확인되면 원전 여부와 관계없이 유지합니다.
    if any(term in haystack for term in OTHER_CONSTRUCTION_TERMS):
        return "타 건설사"

    return None


def parse_entry(entry, language: str, group: str) -> Article | None:
    raw_date = getattr(entry, "published", None) or getattr(entry, "updated", None)
    if not raw_date:
        return None

    try:
        published = date_parser.parse(raw_date).astimezone(KST)
    except Exception:
        return None

    title, publisher_from_title = split_title_and_publisher(
        getattr(entry, "title", "")
    )
    link = getattr(entry, "link", "").strip()

    source = getattr(entry, "source", {})
    publisher = source.get("title", "") if isinstance(source, dict) else ""
    source_url = source.get("href", "") if isinstance(source, dict) else ""
    publisher = publisher.strip() or publisher_from_title

    if not title or not link or not is_news_source(publisher, source_url, title):
        return None

    summary = (
        getattr(entry, "summary", "")
        or getattr(entry, "description", "")
        or ""
    )

    if is_blocked_campaign_slogan(title, summary):
        return None

    if is_excluded_national_singing_contest_article(title, summary):
        return None

    if is_excluded_fastcompany_china_renewable_article(title, summary):
        return None

    # Palisades Goldcorp는 광산회사로 Holtec/Palisades 원전과 무관하므로
    # 어떤 검색경로·분류그룹으로 들어와도 전역에서 제외합니다.
    if is_palisades_goldcorp_non_nuclear_article(title, summary):
        return None

    priority_group = classify_priority_company_group(group, title, summary)
    classified_group = classify_construction_group(priority_group, title, summary)
    if classified_group is None:
        return None

    # LA Pacific Palisades 화재·범죄 기사 등은 어느 검색 그룹에서 들어와도 제외합니다.
    if is_pacific_palisades_non_nuclear_article(title, summary):
        return None

    # 어느 검색경로에서 들어왔든 Holtec 탭으로 분류된 기사는
    # 실제 Holtec 원전·SMR 관련성이 확인되어야 최종 유지합니다.
    if classified_group == "Holtec" and publisher != "Holtec International" and not is_valid_holtec_article(title, summary):
        return None

    if classified_group in {"해외 건설사", "해외 설계사"}:
        if not is_civil_nuclear_relevant(title, summary):
            return None

    # 지역 낙뢰·정전·사고 자체가 중심이고 한전은 복구 주체로만 언급된 기사는
    # 한국전력 주요 동향 탭에서 제외합니다.
    if classified_group == "한국전력" and is_low_value_kepco_local_incident(title, summary):
        return None

    if classified_group == "현대건설" and is_hyundai_volleyball_article(title, summary):
        return None

    description = clean_description(summary, title, publisher)

    return Article(
        title=title,
        link=link,
        published=published,
        language=language,
        group=classified_group,
        publisher=publisher,
        image=extract_image(entry),
        source_url=source_url,
        description=description,
    )


