def _article_country_text(article: Article) -> tuple[str, str]:
    title = article.title.lower()
    full = " ".join(
        [article.title, article.description, article.publisher, article.group]
    ).lower()
    return title, full


def _contains_country_term(text: str, term: str) -> bool:
    """
    국가 키워드 오탐 방지.
    - 영문/숫자 용어는 영숫자 단어 내부 매치를 막습니다.
    - 짧은 한글 국가명(예: 영국, 한국, 미국, 인도)은 사람 이름/일반 단어 내부 매치를 막습니다.
      예: '박영국' -> 영국 아님.
    - 조사/띄어쓰기/문장부호 뒤는 허용합니다.
      예: '영국의 원전', '영국 정부' -> 영국.
    """
    if not text or not term:
        return False

    haystack = text.lower()
    needle = term.lower()

    # 한글이 들어간 키워드
    if re.search(r"[가-힣]", needle):
        # 단어 내부의 짧은 국가명 오탐을 특히 엄격하게 차단
        if len(needle) <= 3 and re.fullmatch(r"[가-힣]+", needle):
            # 앞쪽이 한글이면 사람 이름/복합명사 내부일 가능성이 높음
            pattern = rf"(?<![가-힣]){re.escape(needle)}"
            return re.search(pattern, haystack) is not None

        return needle in haystack

    # 영문/숫자 용어는 영숫자 단어 내부 매치 방지
    pattern = rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])"
    return re.search(pattern, haystack, flags=re.I) is not None


def _country_term_position(text: str, term: str) -> int:
    """_contains_country_term과 같은 규칙으로 첫 등장 위치를 반환합니다."""
    if not text or not term:
        return -1

    haystack = text.lower()
    needle = term.lower()

    if re.search(r"[가-힣]", needle):
        if len(needle) <= 3 and re.fullmatch(r"[가-힣]+", needle):
            m = re.search(rf"(?<![가-힣]){re.escape(needle)}", haystack)
            return m.start() if m else -1
        return haystack.find(needle)

    m = re.search(
        rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])",
        haystack,
        flags=re.I,
    )
    return m.start() if m else -1


def _country_term_count(text: str, term: str) -> int:
    """국가 키워드 등장 횟수를 오탐 방지 규칙으로 계산합니다."""
    if not text or not term:
        return 0

    haystack = text.lower()
    needle = term.lower()

    if re.search(r"[가-힣]", needle):
        if len(needle) <= 3 and re.fullmatch(r"[가-힣]+", needle):
            return len(re.findall(rf"(?<![가-힣]){re.escape(needle)}", haystack))
        return haystack.count(needle)

    return len(
        re.findall(
            rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])",
            haystack,
            flags=re.I,
        )
    )


def _matching_country_codes(text: str, rules: dict[str, tuple[str, ...]]) -> list[str]:
    hits: list[str] = []
    for code, terms in rules.items():
        if any(_contains_country_term(text, term) for term in terms):
            hits.append(code)
    return hits


def _best_country_match(
    title: str,
    full: str,
    rules: dict[str, tuple[str, ...]],
) -> str | None:
    """
    같은 우선순위 안에서 여러 국가가 잡히면
    1) 제목에 직접 등장한 국가
    2) 제목에서 더 앞에 등장한 국가
    3) 전체 기사에서 등장 횟수가 많은 국가
    순으로 대표국가를 선택합니다.
    """
    candidates: list[tuple[int, int, int, str]] = []
    for order, (code, terms) in enumerate(rules.items()):
        title_positions = [
            pos
            for term in terms
            if (pos := _country_term_position(title, term)) >= 0
        ]
        title_pos = min(title_positions) if title_positions else 10**9
        full_count = sum(_country_term_count(full, term) for term in terms)
        if title_pos < 10**9 or full_count > 0:
            in_title_rank = 0 if title_pos < 10**9 else 1
            candidates.append((in_title_rank, title_pos, -full_count, code))
    if not candidates:
        return None
    candidates.sort()
    return candidates[0][3]


def detect_related_countries(article: Article) -> list[str]:
    """
    기사에 실제로 관련된 국가를 모두 찾습니다.
    지도 집계에는 사용하지 않고 기사 카드의 보조 정보로만 사용합니다.
    """
    title, full = _article_country_text(article)
    found: list[str] = []

    for rules in (
        COUNTRY_PROJECT_TERMS,
        COUNTRY_GOVERNMENT_TERMS,
        COUNTRY_EXPLICIT_TERMS,
        COUNTRY_HOME_ENTITY_TERMS,
    ):
        for code in _matching_country_codes(full, rules):
            if code not in found:
                found.append(code)

    primary = detect_article_country(article)
    if primary != "OTHER":
        found = [primary] + [code for code in found if code != primary]
    return found


def detect_article_country(article: Article) -> str:
    """
    대표국가 1개만 반환합니다.
    지도 기사 수는 이 대표국가만 집계하므로 전체 기사 수와 국가별 합계가 일치합니다.

    판정 원칙:
    1) 제목에 직접 적힌 프로젝트/사업 위치
    2) 제목에 직접 적힌 정부·규제기관/국가
    3) 그 다음 본문/미리보기까지 포함해 기존 우선순위 적용
    4) 기업/기관 본국
    5) 기타

    제목에 '영국'이 명시됐는데 미리보기의 다른 국가 표현 때문에
    남아공 등으로 잘못 분류되는 현상을 방지합니다.
    """
    title, full = _article_country_text(article)

    # 제목에 명확히 드러난 국가/프로젝트를 본문 단서보다 우선합니다.
    for rules in (
        COUNTRY_PROJECT_TERMS,
        COUNTRY_GOVERNMENT_TERMS,
        COUNTRY_EXPLICIT_TERMS,
    ):
        code = _best_country_match(title, title, rules)
        if code:
            return code

    # 제목에서 특정되지 않을 때만 본문/설명/출처까지 함께 봅니다.
    for rules in (
        COUNTRY_PROJECT_TERMS,
        COUNTRY_GOVERNMENT_TERMS,
        COUNTRY_EXPLICIT_TERMS,
        COUNTRY_HOME_ENTITY_TERMS,
    ):
        code = _best_country_match(title, full, rules)
        if code:
            return code

    # 영문 기사도 언어 때문에 '기타'로 보내지 않습니다.
    # 다만 국가/프로젝트를 실제로 특정할 근거가 없는 글로벌·국제기구 기사만 OTHER로 남깁니다.
    return "OTHER"




# 같은 사건을 여러 언론사가 보도한 경우 대표기사 아래에 "외 N개 언론사 보도"로 보이기 위한 런타임 메타데이터.
# 화면 생성 중에만 사용하며 archive 구조는 변경하지 않습니다.
_RELATED_COVERAGE_GROUPS: dict[str, list[dict[str, str]]] = {}


def _related_article_payload(article: Article) -> dict[str, str]:
    return {
        "link": article.link or "",
        "publisher": article.publisher or "출처 미확인",
        "title": article.title or "",
    }


def _merge_related_payloads(*payload_lists: list[dict[str, str]]) -> list[dict[str, str]]:
    merged: list[dict[str, str]] = []
    seen: set[tuple[str, str, str]] = set()
    for payload_list in payload_lists:
        for item in payload_list:
            key = (
                str(item.get("link") or ""),
                str(item.get("publisher") or ""),
                normalized(str(item.get("title") or "")),
            )
            if key in seen:
                continue
            seen.add(key)
            merged.append(
                {
                    "link": str(item.get("link") or ""),
                    "publisher": str(item.get("publisher") or "출처 미확인"),
                    "title": str(item.get("title") or ""),
                }
            )
    return merged


def _register_related_coverage(representative: Article, members: list[Article]) -> None:
    rep_link = representative.link or ""
    if not rep_link:
        return

    prior_payloads: list[dict[str, str]] = []
    cleanup_keys: set[str] = set()

    for member in members:
        member_link = member.link or ""
        if member_link and member_link in _RELATED_COVERAGE_GROUPS:
            prior_payloads.extend(_RELATED_COVERAGE_GROUPS[member_link])
            cleanup_keys.add(member_link)

    candidate_payloads = [_related_article_payload(member) for member in members]
    merged = _merge_related_payloads(prior_payloads, candidate_payloads)

    # 대표기사 자체는 대체 언론사 목록에서 제외
    alternatives = [
        item for item in merged
        if item.get("link") != rep_link
    ]

    for key in cleanup_keys:
        if key != rep_link:
            _RELATED_COVERAGE_GROUPS.pop(key, None)

    if alternatives:
        _RELATED_COVERAGE_GROUPS[rep_link] = alternatives
    else:
        _RELATED_COVERAGE_GROUPS.pop(rep_link, None)


def _related_coverage_html(article: Article) -> str:
    alternatives = _RELATED_COVERAGE_GROUPS.get(article.link or "", [])
    if not alternatives:
        return ""

    safe_items = []
    for item in alternatives:
        link = escape(item.get("link") or "")
        publisher = escape(item.get("publisher") or "출처 미확인")
        title = escape(item.get("title") or "")
        safe_items.append(
            f'<a class="related-coverage-link" href="{link}" target="_blank" rel="noopener">'
            f'<span class="related-coverage-publisher">{publisher}</span>'
            f'<span class="related-coverage-title">{title}</span>'
            '</a>'
        )

    return (
        f'<button class="related-coverage-button" type="button" '
        f'aria-expanded="false">외 {len(alternatives)}개 언론사 보도</button>'
        f'<div class="related-coverage-source" hidden>{"".join(safe_items)}</div>'
    )




def _korean_business_meeting_event_key(article: Article) -> str | None:
    """
    국내 주요 인사 간 동일 회동/만찬 보도가 제목 표현 차이로 덜 묶이는 경우를 보완합니다.
    특정 기사 제목 자체를 하드코딩하지 않고,
    핵심 인물 + 회동 행위 + 공통 의제를 기준으로 사건 키를 생성합니다.
    """
    hay = normalized(f"{article.title or ''} {article.description or ''}")

    people = []
    person_terms = (
        ("이재명", ("이재명", "대통령")),
        ("최태원", ("최태원",)),
    )
    for canonical, aliases in person_terms:
        if any(alias in hay for alias in aliases):
            people.append(canonical)

    # 이 사례는 두 핵심 인물이 모두 확인될 때만 강한 사건키 적용
    if not {"이재명", "최태원"}.issubset(set(people)):
        return None

    meeting_terms = (
        "만찬", "회동", "면담", "오찬", "회담", "미팅",
        "전격만찬", "비공개만찬", "만찬회동", "만찬자리",
    )
    if not any(term in hay for term in meeting_terms):
        return None

    agenda_groups = []
    agenda_map = (
        ("대미투자", ("대미투자", "대미 투자", "미국투자", "미국 투자", "대미 투자 논의")),
        ("반도체", ("반도체", "반도체투자", "반도체 투자")),
        ("sk", ("sk그룹", "sk 그룹", "sk")),
    )
    for canonical, aliases in agenda_map:
        if any(alias in hay for alias in aliases):
            agenda_groups.append(canonical)

    # 최소 1개 공통 의제가 있어야 같은 이벤트로 간주
    if not agenda_groups:
        return None

    return "국내회동|이재명|최태원|" + "|".join(sorted(set(agenda_groups)))


def _kepco_affiliate_press_event_key(article: Article) -> str | None:
    """
    한전 계열사 보도자료성 기사에서 제목 표현이 달라도 동일 행사를 묶기 위한 키.

    현재 반복 노출이 확인된 한전KDN 사례:
    - 기후위기/여름나기 취약계층 물품 지원
    - 전남개발공사와 스마트 주거서비스·에너지 플랫폼 아이디어 공유
    """
    if (article.group or "") != "한전 계열사":
        return None

    hay = normalized(f"{article.title or ''} {article.description or ''}")

    # 한전KDN 기사에만 적용하여 다른 계열사끼리 과도하게 묶이지 않게 함.
    if not any(token in hay for token in ("한전kdn", "kepcokdn", "kepco kdn")):
        return None

    support_subject = any(
        token in hay
        for token in (
            "취약계층", "기후위기취약계층", "기후위기 취약계층",
            "에너지취약계층", "에너지 취약계층",
        )
    )
    support_action = any(
        token in hay
        for token in (
            "여름나기", "물품지원", "물품 지원", "지원물품",
            "지원 물품", "물품전달", "물품 전달", "사회공헌",
        )
    )
    if support_subject and support_action:
        return "한전KDN|취약계층|여름나기물품지원"

    housing_partner = any(
        token in hay
        for token in ("전남개발공사", "전남 개발공사")
    )
    housing_subject = any(
        token in hay
        for token in (
            "스마트주거", "스마트 주거", "주거서비스", "주거 서비스",
            "공공임대주택", "공공 임대주택", "임대주택",
            "에너지플랫폼", "에너지 플랫폼",
        )
    )
    housing_action = any(
        token in hay
        for token in (
            "아이디어공유", "아이디어 공유", "공유회",
            "구축방안", "구축 방안", "방안모색", "방안 모색",
            "발굴", "서비스발굴", "서비스 발굴",
            "스마트주거서비스", "스마트 주거서비스",
        )
    )
    if housing_partner and housing_subject and housing_action:
        return "한전KDN|전남개발공사|스마트주거에너지플랫폼"

    return None



def _ministry_personnel_event_key(article: Article) -> str | None:
    """
    관계부처의 동일 인사발령 보도를 언론사가 달라도 하나로 묶기 위한 사건 키.
    같은 날짜 + 같은 부처 + 동일 인사유형 신호가 있을 때만 적용합니다.
    """
    if (article.group or "") != "원전 관계부처":
        return None

    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\\s+", "", hay)

    ministry = None
    ministry_aliases = (
        ("기후에너지환경부", ("기후에너지환경부", "기후부")),
        ("산업통상부", ("산업통상부", "산업통상자원부", "산업부")),
        ("과학기술정보통신부", ("과학기술정보통신부", "과기정통부", "과기부")),
    )
    for canonical, aliases in ministry_aliases:
        if any(alias.replace(" ", "") in compact for alias in aliases):
            ministry = canonical
            break
    if not ministry:
        return None

    personnel_terms = (
        "인사", "인사발령", "신규보임", "전보", "보임", "임명", "승진",
        "과장급", "국장급", "실장급", "과장급신규보임", "과장급전보",
    )
    if not any(term.replace(" ", "") in compact for term in personnel_terms):
        return None

    # 단순 인사 관련 일반 기사까지 합치지 않도록 발령 형태 신호를 하나 더 요구.
    action_terms = ("신규보임", "전보", "보임", "임명", "승진", "인사발령")
    if not any(term.replace(" ", "") in compact for term in action_terms):
        return None

    return f"관계부처인사|{ministry}|{article.published.astimezone(KST).strftime('%Y-%m-%d')}"


def _us_house_mast_coupang_event_key(article: Article) -> str | None:
    """
    브라이언 매스트 미 하원 외교위원장의 쿠팡/대미투자 관련 동일 발언 보도를 묶습니다.
    별도의 반도체 현지생산 압박 등 다른 미국 이슈는 포함하지 않습니다.
    """
    if (article.group or "") != "원전 대미투자":
        return None

    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\\s+", "", hay)

    mast_terms = (
        "브라이언매스트", "brianmast", "하원외교위원장", "미하원외교위원장",
    )
    if not any(term in compact for term in mast_terms):
        return None

    if "쿠팡" not in compact and "coupang" not in compact:
        return None

    context_terms = (
        "대미투자", "미국기업", "한국정부", "한미훈련", "압박", "피해줘", "피해",
    )
    if not any(term in compact for term in context_terms):
        return None

    return f"미하원외교위원장|브라이언매스트|쿠팡대미투자|{article.published.astimezone(KST).strftime('%Y-%m-%d')}"


def _khnp_org_culture_event_key(article: Article) -> str | None:
    """
    한수원 동일 보도자료 중 제목 표현이 크게 달라지는 조직문화혁신/주니어보드 기사를
    하나의 사건으로 묶기 위한 보수적 사건 키입니다.

    예: "조직문화혁신 주니어보드 신설", "실천하고 변화하는 조직문화혁신 주니어보드" 등.
    한수원 기사이면서 김희천/조직문화혁신/주니어보드 핵심 신호가 충분히 겹칠 때만 적용합니다.
    """
    if (article.group or "") != "한국수력원자력":
        return None

    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\s+", "", hay)

    has_khnp = any(
        token in compact
        for token in ("한국수력원자력", "한수원", "khnp")
    )
    if not has_khnp:
        return None

    signals = 0
    if "김희천" in compact:
        signals += 1
    if "조직문화혁신" in compact or ("조직문화" in compact and "혁신" in compact):
        signals += 1
    if "주니어보드" in compact or "juniorboard" in compact:
        signals += 1
    if "직원주도" in compact or "실천하고변화" in compact or "실천과변화" in compact:
        signals += 1

    # 회사명만 같은 일반 인사/문화 기사가 섞이지 않도록 핵심 신호 2개 이상을 요구합니다.
    if signals < 2:
        return None

    return "KHNP|김희천|조직문화혁신|주니어보드"



def _cigre_company_event_key(article: Article) -> str | None:
    """
    CIGRE/시그레 동일 행사 보도를 회사 + 핵심 주제 기준으로 묶습니다.

    같은 행사라는 이유만으로 전부 합치지 않고,
    회사/기관 조합과 발표 주제가 함께 같을 때만 동일 사건 키를 만듭니다.
    예:
    - 한전 + LS전선 + 해저케이블 통합 자산관리 플랫폼
    - 대한전선 + CIGRE + 해저케이블/턴키 솔루션
    - 한전 + EPRI + 재생에너지 계통 기술협력 (위 사건들과 별도)
    """
    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\s+", "", hay)

    if not any(token in compact for token in ("cigre", "시그레")):
        return None

    entity_aliases = (
        ("KEPCO", ("한국전력", "한국전력공사", "한전", "kepco")),
        ("LS전선", ("ls전선", "lscable", "ls cable")),
        ("대한전선", ("대한전선", "taihan", "taihan cable")),
        ("EPRI", ("epri", "미국전력연구원")),
        ("효성중공업", ("효성중공업", "hyosung heavy industries")),
        ("LS일렉트릭", ("ls일렉트릭", "ls electric")),
    )

    entities = []
    for canonical, aliases in entity_aliases:
        if any(alias.replace(" ", "") in compact for alias in aliases):
            entities.append(canonical)

    if not entities:
        return None

    topic = None

    # 한전-LS전선의 SFL-R × CAMS / 해저케이블 통합 자산관리 플랫폼
    if (
        any(x in compact for x in ("해저케이블", "submarinecable", "subseacable"))
        and any(x in compact for x in (
            "자산관리", "통합자산관리", "assetmanagement",
            "sfl-r", "sflr", "cams", "플랫폼",
        ))
    ):
        topic = "해저케이블자산관리"

    # 대한전선의 CIGRE 해저케이블 턴키/솔루션 전시
    elif (
        "대한전선" in entities
        and any(x in compact for x in ("해저케이블", "submarinecable", "subseacable"))
        and any(x in compact for x in (
            "턴키", "turnkey", "솔루션", "solution",
            "전시", "선보여", "참가", "유럽공략",
        ))
    ):
        topic = "대한전선해저케이블솔루션"

    # 한전-EPRI 재생에너지 계통 수용성/기술개발 협력
    elif (
        "KEPCO" in entities
        and "EPRI" in entities
        and any(x in compact for x in (
            "재생에너지", "계통수용", "계통수용성",
            "기술개발", "협력", "맞손", "mou",
        ))
    ):
        topic = "한전EPRI재생에너지계통협력"

    else:
        # 일반 CIGRE 보도는 과도하게 합치지 않음
        return None

    entity_key = "+".join(sorted(set(entities)))
    return f"CIGRE|{entity_key}|{topic}"



def _kepco_epri_grid_cooperation_event_key(article: Article) -> str | None:
    """
    한전-미국 EPRI의 재생에너지 계통 수용성/기술개발 협력 동일 보도 묶음.

    CIGRE 문구가 제목/미리보기에 없어도 동일 사건이면 잡습니다.
    반대로 LS전선/CIGRE 해저케이블 기사와는 주체·주제가 달라 절대 같은 키가 되지 않습니다.
    """
    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\s+", "", hay)

    has_kepco = any(
        x in compact
        for x in ("한국전력", "한국전력공사", "한전", "kepco")
    )
    has_epri = any(
        x in compact
        for x in ("epri", "미국전력연구원", "electricpowerresearchinstitute")
    )
    if not (has_kepco and has_epri):
        return None

    renewable_grid_terms = (
        "재생에너지", "신재생에너지",
        "계통수용성", "계통수용", "전력계통",
        "gridintegration", "gridhosting", "hostingcapacity",
    )
    cooperation_terms = (
        "기술개발", "공동개발", "공동연구",
        "협력", "맞손", "협약", "mou", "실증",
    )

    has_grid_topic = any(x.replace(" ", "") in compact for x in renewable_grid_terms)
    has_cooperation = any(x.replace(" ", "") in compact for x in cooperation_terms)

    if has_grid_topic and has_cooperation:
        return "KEPCO|EPRI|RENEWABLE_GRID_INTEGRATION_COOPERATION"

    return None



def _us_house_coupang_pressure_event_key(article: Article) -> str | None:
    """
    美 하원 외교위원장 브라이언 매스트의
    쿠팡/미국기업 피해 주장 + 한국 대미투자 압박 관련 동일 보도를 묶습니다.

    메모리칩 현지생산 압박 등 다른 대미 압박 이슈는 별도 유지합니다.
    """
    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\s+", "", hay)

    mast_terms = (
        "브라이언매스트", "브라이언매스트외교위원장",
        "매스트외교위원장", "brianmast"
    )
    house_terms = (
        "미하원외교위원장", "하원외교위원장",
        "미국하원외교위원장", "houseforeignaffairs"
    )
    coupang_terms = ("쿠팡", "coupang")
    pressure_terms = (
        "대미투자", "투자압박", "미국기업", "피해줘",
        "피해주", "압박", "무슨이득", "투자"
    )

    has_mast = any(x in compact for x in mast_terms)
    has_house = any(x in compact for x in house_terms)
    has_coupang = any(x in compact for x in coupang_terms)
    has_pressure = any(x in compact for x in pressure_terms)

    # 핵심 사건: Brian Mast/미 하원 외교위원장 + Coupang + 대미투자/미국기업 압박
    if (has_mast or has_house) and has_coupang and has_pressure:
        return "US_HOUSE_FOREIGN_AFFAIRS|BRIAN_MAST|COUPANG|KOREA_INVESTMENT_PRESSURE"

    return None




def _daewoo_vietnam_minister_meeting_event_key(article: Article) -> str | None:
    """
    대우건설 정원주 회장과 베트남 산업통상부 장관의
    원전/LNG/에너지 인프라 협력 면담 보도를 동일 사건으로 묶기 위한 키.

    언론사별 제목 표현이 달라도 아래 핵심 구조가 모두 확인되면 같은 사건으로 봅니다.
    - 대우건설
    - 베트남
    - 산업통상부 장관(또는 Ministry/Minister of Industry and Trade)
    - 면담/회동/협력 논의
    """
    if (article.group or "") not in {"타 건설사", "주요 건설사"}:
        return None

    hay = normalized(f"{article.title or ''} {article.description or ''}")
    compact = re.sub(r"\s+", "", hay)

    company_ok = any(x in compact for x in (
        "대우건설", "daewooe&c", "daewooengineeringconstruction",
    ))
    country_ok = any(x in compact for x in (
        "베트남", "vietnam",
    ))
    counterpart_ok = any(x in compact for x in (
        "산업통상부장관",
        "베트남산업통상부",
        "산업무역부장관",
        "산업무역부",
        "ministerofindustryandtrade",
        "ministryofindustryandtrade",
    ))
    meeting_ok = any(x in compact for x in (
        "면담", "회동", "회담", "미팅", "만나", "협력논의", "논의",
        "meeting", "metwith", "talks",
    ))

    if company_ok and country_ok and counterpart_ok and meeting_ok:
        return "DAEWOO_EC|VIETNAM|INDUSTRY_TRADE_MINISTER|MEETING"

    return None


def _same_publisher_followup_event(a: Article, b: Article) -> bool:
    """
    같은 언론사의 후속/종합 기사도 동일 사건이면 하나로 묶습니다.

    단, 같은 언론사 기사라는 이유만으로 묶지 않고 다음을 강하게 확인합니다.
    - 같은 기사 탭
    - 게시일 차이 최대 1일
    - 국가가 명확히 다르면 제외
    - 사건 단계가 명확히 다르면 제외
    - 핵심 토큰/제목 유사도/전체 유사도가 충분히 높아야 함
    - 장소/재난/프로젝트/기관 등 구체 앵커가 겹치면 추가 가중
    """
    publisher_a = (a.publisher or "").strip()
    publisher_b = (b.publisher or "").strip()
    if not publisher_a or not publisher_b or publisher_a != publisher_b:
        return False

    if a.group != b.group:
        return False

    day_a = a.published.astimezone(KST).date()
    day_b = b.published.astimezone(KST).date()
    if abs((day_a - day_b).days) > 1:
        return False

    country_a = detect_article_country(a)
    country_b = detect_article_country(b)
    if (
        country_a not in {"", "OTHER"}
        and country_b not in {"", "OTHER"}
        and country_a != country_b
    ):
        return False

    stage_a = _thumbnail_event_stage(a)
    stage_b = _thumbnail_event_stage(b)
    if stage_a and stage_b and stage_a != stage_b:
        return False

    hay_a = normalized(f"{a.title or ''} {a.description or ''}")
    hay_b = normalized(f"{b.title or ''} {b.description or ''}")

    tokens_a = _thumbnail_event_tokens(a)
    tokens_b = _thumbnail_event_tokens(b)
    if not tokens_a or not tokens_b:
        return False

    common = tokens_a & tokens_b
    containment = len(common) / max(1, min(len(tokens_a), len(tokens_b)))
    title_similarity = semantic_duplicate_score(a.title or "", b.title or "")
    full_similarity = article_ngram_similarity(a, b)

    # 구체 사건/장소/프로젝트 앵커
    anchor_patterns = (
        r"[가-힣A-Za-z0-9]+(?:지구|구역|사업|프로젝트|원전|발전소|호기|센터|공장|현장|시설)",
        r"[가-힣]{2,10}(?:시|군|구|주|도)",
        r"(?:홍수|산사태|지진|태풍|폭우|산불|침수|붕괴|폭발|화재)",
        r"(?:네팔|티베트|라오스|베트남|우크라이나|미국|중국|일본|한국)",
        r"(?:한국수력원자력|한수원|한국전력|한전|현대건설|대우건설|두산에너빌리티|삼성물산|GS건설|포스코이앤씨|SK에코플랜트)",
    )

    anchors_a: set[str] = set()
    anchors_b: set[str] = set()
    for pattern in anchor_patterns:
        anchors_a.update(re.findall(pattern, hay_a, flags=re.I))
        anchors_b.update(re.findall(pattern, hay_b, flags=re.I))
    common_anchors = {x for x in anchors_a & anchors_b if len(x) >= 2}

    # 같은 언론사 후속보도는 제목이 업데이트되며 숫자가 달라질 수 있으므로
    # 숫자 변화 자체는 별개 사건으로 보지 않습니다.
    if common_anchors:
        if len(common) >= 4 and containment >= 0.55 and full_similarity >= 0.38:
            return True
        if len(common) >= 3 and containment >= 0.68 and title_similarity >= 0.40:
            return True

    # 앵커 추출이 안 돼도 제목/본문 유사도가 매우 높으면 동일 후속보도로 인정
    if len(common) >= 5 and containment >= 0.68 and full_similarity >= 0.48:
        return True

    if title_similarity >= 0.62 and full_similarity >= 0.44:
        return True

    return False


def _same_content_event_for_grouping(a: Article, b: Article) -> bool:
    """
    대표기사 묶음용 동일사건 판정.

    핵심 원칙:
    - 같은 날짜
    - 같은 기사 탭
    - 서로 다른 언론사
    - 국가가 명확히 다르면 제외
    - 계약/착공/준공/선정 등 사건 단계가 명확히 다르면 제외
    - 핵심 주체 + 대상(프로젝트/기관/설비) + 행위가 같아야 묶음

    제목 표현이 달라도 설명문까지 포함한 사건구조가 같으면 묶되,
    단순히 같은 회사명이 들어간 브리핑/종합기사까지 합쳐지지 않도록
    '대상 앵커'와 '행위 앵커'를 추가 확인합니다.
    """
    publisher_a = (a.publisher or "").strip()
    publisher_b = (b.publisher or "").strip()
    if not publisher_a or not publisher_b:
        return False

    # 같은 언론사 기사도 동일 사건의 후속/종합 보도라면 묶습니다.
    # 다만 오병합 방지를 위해 별도의 더 강한 기준을 사용합니다.
    if publisher_a == publisher_b:
        return _same_publisher_followup_event(a, b)

    date_a_obj = a.published.astimezone(KST).date()
    date_b_obj = b.published.astimezone(KST).date()
    date_a = date_a_obj.strftime("%Y-%m-%d")
    date_b = date_b_obj.strftime("%Y-%m-%d")

    if a.group != b.group:
        return False

    # 대우건설 정원주 회장-베트남 산업통상부 장관 면담 동일 보도
    daewoo_vn_event_a = _daewoo_vietnam_minister_meeting_event_key(a)
    daewoo_vn_event_b = _daewoo_vietnam_minister_meeting_event_key(b)
    if (
        daewoo_vn_event_a
        and daewoo_vn_event_a == daewoo_vn_event_b
        and abs((date_a_obj - date_b_obj).days) <= 1
    ):
        return True

    # 美 하원 외교위원장 Brian Mast의 쿠팡/대미투자 압박 동일 보도
    mast_event_a = _us_house_coupang_pressure_event_key(a)
    mast_event_b = _us_house_coupang_pressure_event_key(b)
    if mast_event_a and mast_event_a == mast_event_b:
        # 동일 발언 보도는 언론사 게시 시차를 고려해 최대 2일 차이까지 동일 사건 처리
        if abs((date_a_obj - date_b_obj).days) <= 2:
            return True

    # 한전-EPRI 재생에너지 계통 수용성/기술개발 협력:
    # 기사 제목에 CIGRE가 없어도 같은 보도자료/협력 건이면 최대 2일 차이까지 묶습니다.
    epri_event_a = _kepco_epri_grid_cooperation_event_key(a)
    epri_event_b = _kepco_epri_grid_cooperation_event_key(b)
    if epri_event_a and epri_event_a == epri_event_b:
        if abs((date_a_obj - date_b_obj).days) <= 2:
            return True

    # CIGRE/시그레 동일 행사 보도:
    # 같은 날짜 + 같은 회사/기관 조합 + 같은 발표 주제일 때만 묶습니다.
    cigre_event_a = _cigre_company_event_key(a)
    cigre_event_b = _cigre_company_event_key(b)
    if cigre_event_a and cigre_event_a == cigre_event_b:
        # 동일 CIGRE 행사 보도는 언론사별 게시 시점 차이로 날짜가 하루 이상
        # 달라질 수 있으므로, 최대 2일 차이까지 같은 사건으로 묶습니다.
        if abs((date_a_obj - date_b_obj).days) <= 2:
            return True

    # 관계부처 동일 인사발령은 언론사가 달라도 같은 사건으로 묶습니다.
    ministry_event_a = _ministry_personnel_event_key(a)
    ministry_event_b = _ministry_personnel_event_key(b)
    if ministry_event_a and ministry_event_a == ministry_event_b and date_a == date_b:
        return True

    # 브라이언 매스트 美 하원 외교위원장의 쿠팡/대미투자 관련 동일 발언 보도 묶음.
    mast_event_a = _us_house_mast_coupang_event_key(a)
    mast_event_b = _us_house_mast_coupang_event_key(b)
    if mast_event_a and mast_event_a == mast_event_b and date_a == date_b:
        return True

    # 한수원 조직문화혁신/주니어보드 동일 보도자료는 제목 표현이 크게 달라도
    # 대표기사 1건 + "외 N개 언론사 보도"로 묶습니다.
    khnp_event_a = _khnp_org_culture_event_key(a)
    khnp_event_b = _khnp_org_culture_event_key(b)
    if khnp_event_a and khnp_event_a == khnp_event_b and date_a == date_b:
        return True

    meeting_event_a_early = _korean_business_meeting_event_key(a)
    meeting_event_b_early = _korean_business_meeting_event_key(b)
    if (
        meeting_event_a_early
        and meeting_event_a_early == meeting_event_b_early
        and abs((date_a_obj - date_b_obj).days) <= 1
    ):
        return True

    affiliate_event_a_early = _kepco_affiliate_press_event_key(a)
    affiliate_event_b_early = _kepco_affiliate_press_event_key(b)

    # 같은 한전 계열사 보도자료가 자정 전후로 하루 차이 나게 게재되는 경우 허용.
    # 정확히 같은 사건 키일 때만 ±1일을 허용해 과도한 병합을 막습니다.
    if (
        affiliate_event_a_early
        and affiliate_event_a_early == affiliate_event_b_early
        and abs((date_a_obj - date_b_obj).days) <= 1
    ):
        return True

    # 일반 동일사건 기사도 언론사별 게시시각/자정 경계 차이를 고려해
    # 최대 ±1일까지 비교합니다. 2일 차이는 위의 명시적 event-key가 같은 경우만 허용합니다.
    date_gap_days = abs((date_a_obj - date_b_obj).days)
    if date_gap_days > 1:
        return False

    country_a = detect_article_country(a)
    country_b = detect_article_country(b)
    if (
        country_a not in {"", "OTHER"}
        and country_b not in {"", "OTHER"}
        and country_a != country_b
    ):
        return False

    stage_a = _thumbnail_event_stage(a)
    stage_b = _thumbnail_event_stage(b)
    if stage_a and stage_b and stage_a != stage_b:
        return False

    hay_a = normalized(f"{a.title or ''} {a.description or ''}")
    hay_b = normalized(f"{b.title or ''} {b.description or ''}")

    # 국내 주요 인사 회동/만찬 기사:
    # 제목 표현이 크게 달라도 핵심 인물 + 행위 + 의제가 같으면 동일 사건으로 묶음.
    meeting_event_a = _korean_business_meeting_event_key(a)
    meeting_event_b = _korean_business_meeting_event_key(b)
    if meeting_event_a and meeting_event_a == meeting_event_b:
        return True

    # 한전 계열사 보도자료는 동일 행사라도 제목이
    # '물품 지원/건강한 여름나기', '아이디어 공유/에너지 플랫폼 구축'처럼
    # 크게 달라질 수 있으므로 사건 구조 키를 먼저 비교합니다.
    affiliate_event_a = affiliate_event_a_early
    affiliate_event_b = affiliate_event_b_early
    if affiliate_event_a and affiliate_event_a == affiliate_event_b:
        return True

    # 실제 동일/유사 이미지 + 동일 내용은 가장 강한 신호
    if _same_thumbnail_same_event(a, b):
        return True

    # 사건의 '대상'이 되는 고유 앵커.
    # 숫자/단지명/프로젝트명/상대기관명이 제목 또는 설명문에 공통으로 있을수록
    # 같은 보도자료 계열일 가능성이 높습니다.
    anchor_patterns = (
        r"[가-힣A-Za-z0-9]+(?:\d+)?단지",
        r"[가-힣A-Za-z0-9]+(?:지구|구역|사업|프로젝트|원전|발전소|호기|센터|공장|현장|시설)",
        r"[가-힣]{2,8}(?:시|군|구)",
        r"(?:건식저장시설|건식 저장시설|사용후핵연료|상생협력금|협력금)",
        r"(?:신한은행|국민은행|우리은행|하나은행|농협은행|기업은행|산업은행)",
        r"(?:한국수력원자력|한수원|한국전력|한전|현대건설|현대엔지니어링|대우건설|DL이앤씨|삼성물산|GS건설|롯데건설|포스코이앤씨|SK에코플랜트|두산에너빌리티)",
    )

    anchors_a: set[str] = set()
    anchors_b: set[str] = set()
    for pattern in anchor_patterns:
        anchors_a.update(re.findall(pattern, hay_a, flags=re.I))
        anchors_b.update(re.findall(pattern, hay_b, flags=re.I))

    common_anchors = {x for x in anchors_a & anchors_b if len(x) >= 3}

    # 행위 앵커는 표현이 달라도 같은 이벤트 단계인지 보기 위한 보조 신호.
    action_groups = (
        ("업무협약", "협약", "mou", "맞손", "협력", "협력 논의", "협력논의"),
        ("면담", "회동", "간담회", "논의", "협의", "회의", "만나"),
        ("요청", "촉구", "건의", "제안", "주문"),
        ("갈등", "반발", "논란", "상생", "상생협력", "주민소통", "주민 소통"),
        ("금융", "자금조달", "금융지원", "사업비", "대출", "지원금", "협력금"),
        ("공동개발", "기술개발", "개발", "공동 기술개발", "실증", "연구개발"),
        ("수주", "선정", "우선협상대상자", "낙찰"),
        ("계약", "본계약", "체결"),
        ("착공", "기공"),
        ("준공", "완공"),
        ("승인", "허가", "인가", "인허가"),
        ("발표", "공개", "출범", "개최"),
        ("점검", "현장점검", "현장 점검", "방문"),
    )

    def action_signature(hay: str) -> set[int]:
        sig: set[int] = set()
        for idx, variants in enumerate(action_groups):
            if any(normalized(v) in hay for v in variants):
                sig.add(idx)
        return sig

    actions_a = action_signature(hay_a)
    actions_b = action_signature(hay_b)
    common_actions = actions_a & actions_b

    tokens_a = _thumbnail_event_tokens(a)
    tokens_b = _thumbnail_event_tokens(b)
    if not tokens_a or not tokens_b:
        return False

    common = tokens_a & tokens_b
    containment = len(common) / max(1, min(len(tokens_a), len(tokens_b)))
    title_similarity = semantic_duplicate_score(a.title or "", b.title or "")
    full_similarity = article_ngram_similarity(a, b)

    # 기존 일반 동일사건 판정은 유지하되, 고유 대상 또는 충분한 사건 토큰이 있어야 수용
    if same_event_general(a, b):
        if common_anchors and (common_actions or len(common) >= 4):
            return True
        if len(common) >= 5 and containment >= 0.55:
            return True

    # 보도자료성 제목 변형
    if (
        is_same_event(a.title or "", b.title or "")
        or same_press_release_event(a.title or "", b.title or "")
    ):
        if common_anchors and (
            common_actions
            or containment >= 0.45
            or title_similarity >= 0.42
            or full_similarity >= 0.40
        ):
            return True
        if len(common) >= 4 and containment >= 0.58 and full_similarity >= 0.42:
            return True

    # 구체 프로젝트/기관/지역/시설 앵커 + 같은 행위축이 있으면
    # 언론사별 제목 표현이 상당히 달라도 동일 사건으로 묶습니다.
    if common_anchors and common_actions:
        if len(common) >= 2 and containment >= 0.38 and full_similarity >= 0.30:
            return True
        if len(common) >= 3 and title_similarity >= 0.31:
            return True

    # 공통 앵커가 있으면서 핵심 사건 토큰이 충분하면,
    # 행위 표현 자체가 달라도 같은 보도자료/사건으로 인정합니다.
    if common_anchors:
        if len(common) >= 4 and containment >= 0.50 and full_similarity >= 0.35:
            return True
        if len(common) >= 3 and containment >= 0.62 and title_similarity >= 0.38:
            return True

    # 일반 판정도 한 단계 완화하되 회사명 하나만 같은 수준으로는 묶지 않습니다.
    if len(common) >= 4 and containment >= 0.52 and full_similarity >= 0.36:
        return True

    if len(common) >= 3 and containment >= 0.66 and full_similarity >= 0.44:
        return True

    return False


def _group_confirmed_related_articles(
    articles: list[Article],
) -> tuple[list[Article], int]:
    """
    같은 사건의 타 언론사 보도를 연결요소(cluster) 단위로 묶습니다.

    SPEED OPTIMIZED:
    - 먼저 날짜 + 기사탭으로 후보군을 분리
    - 후보군 안에서만 1회씩 pair 비교
    - Union-Find로 A-B, B-C 연결관계까지 한 번에 병합
    - 이전의 cluster 전체 재탐색/while 반복을 제거

    동일사건 판정 기준 자체는 _same_content_event_for_grouping()을 그대로 사용합니다.
    """
    if len(articles) <= 1:
        return list(articles), 0

    ordered = sorted(articles, key=lambda x: x.published, reverse=True)

    # 같은 사건이 자정 전후/다음 날 재보도되는 경우까지 묶기 위해
    # 탭 단위로 후보군을 만들고 pair 단계에서 날짜 차이(최대 2일)를 제한합니다.
    buckets: dict[str, list[Article]] = {}
    for article in ordered:
        key = article.group or ""
        buckets.setdefault(key, []).append(article)

    result: list[Article] = []
    grouped_count = 0

    for bucket_articles in buckets.values():
        n = len(bucket_articles)
        if n == 1:
            result.append(bucket_articles[0])
            continue

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a_idx: int, b_idx: int) -> None:
            root_a = find(a_idx)
            root_b = find(b_idx)
            if root_a == root_b:
                return
            if rank[root_a] < rank[root_b]:
                root_a, root_b = root_b, root_a
            parent[root_b] = root_a
            if rank[root_a] == rank[root_b]:
                rank[root_a] += 1

        # 국가/언론사 등 매우 싼 조건을 먼저 걸러 비싼 similarity 계산을 줄입니다.
        countries = [detect_article_country(a) for a in bucket_articles]
        publishers = [(a.publisher or "").strip() for a in bucket_articles]
        article_days = [a.published.astimezone(KST).date() for a in bucket_articles]

        for i in range(n):
            for j in range(i + 1, n):
                if not publishers[i] or not publishers[j]:
                    continue

                # 명시적 event-key 중 일부가 ±2일까지 허용되므로 후보 비교도 2일까지만.
                if abs((article_days[i] - article_days[j]).days) > 2:
                    continue

                country_i = countries[i]
                country_j = countries[j]
                if (
                    country_i not in {"", "OTHER"}
                    and country_j not in {"", "OTHER"}
                    and country_i != country_j
                ):
                    continue

                if _same_content_event_for_grouping(
                    bucket_articles[i],
                    bucket_articles[j],
                ):
                    union(i, j)

        clusters: dict[int, list[Article]] = {}
        for idx, article in enumerate(bucket_articles):
            clusters.setdefault(find(idx), []).append(article)

        for cluster in clusters.values():
            unique_members: list[Article] = []
            seen_member_keys: set[tuple[str, str, str]] = set()

            for member in cluster:
                key = (
                    member.link or "",
                    member.publisher or "",
                    normalized(member.title or ""),
                )
                if key in seen_member_keys:
                    continue
                seen_member_keys.add(key)
                unique_members.append(member)

            representative = max(unique_members, key=_article_rep_score)
            result.append(representative)

            if len(unique_members) > 1:
                grouped_count += len(unique_members) - 1
                _register_related_coverage(representative, unique_members)

    result = sorted(result, key=lambda x: x.published, reverse=True)

    # 한전 계열사 보도자료 2차 병합:
    # 동일 사건 키가 언론사별 게재시각 차이로 ±1일에 걸친 경우만 추가 병합합니다.
    affiliate_result: list[Article] = []
    affiliate_grouped_count = 0

    for article in result:
        event_key = _kepco_affiliate_press_event_key(article)
        if not event_key:
            affiliate_result.append(article)
            continue

        article_day = article.published.astimezone(KST).date()
        matched_idx = None

        for idx, kept in enumerate(affiliate_result):
            if (article.publisher or "").strip() == (kept.publisher or "").strip():
                continue

            kept_key = _kepco_affiliate_press_event_key(kept)
            if kept_key != event_key:
                continue

            kept_day = kept.published.astimezone(KST).date()
            if abs((article_day - kept_day).days) <= 1:
                matched_idx = idx
                break

        if matched_idx is None:
            affiliate_result.append(article)
            continue

        kept = affiliate_result[matched_idx]
        members = [kept, article]
        representative = max(members, key=_article_rep_score)
        _register_related_coverage(representative, members)
        affiliate_result[matched_idx] = representative
        affiliate_grouped_count += 1

    return (
        sorted(affiliate_result, key=lambda x: x.published, reverse=True),
        grouped_count + affiliate_grouped_count,
    )


def render_card(
    article: Article,
    number: int,
    is_new: bool = False,
) -> str:
    ensure_article_display_metadata(article)
    enforce_kepco_kdn_group(article)

    if article.image:
        image_html = (
            f'<img src="{escape(article.image)}" alt="" '
            'loading="lazy" referrerpolicy="no-referrer">'
        )
    else:
        image_html = '<div class="no-image">NUCLEAR<br>NEWS</div>'

    new_badge = '<span class="new-badge">NEW</span>' if is_new else ''
    snippet_text = article.description.strip()
    snippet_html = (
        f'<div class="article-snippet">{escape(snippet_text)}</div>'
        if snippet_text
        else '<div class="article-snippet article-snippet-empty">미리보기 정보 없음</div>'
    )

    search_text = ' '.join(
        [
            article.title,
            article.publisher,
            article.group,
            article.description,
        ]
    ).lower()
    primary_country = detect_article_country(article)


    return f"""
<article class="preview-card{' new-article' if is_new else ''}"
  data-url="{escape(article.link)}"
  data-title="{escape(article.title)}"
  data-publisher="{escape(article.publisher)}"
  data-group="{escape(article.group)}"
  data-language="{escape(article.language)}"
  data-priority="{_group_article_priority(article, article.group)[0]}"
  data-published="{article.published.timestamp():.0f}"
  data-country="{primary_country}"
  data-search="{escape(search_text)}"
  tabindex="0" role="link">
  <div class="preview-copy">
    <div class="article-content-column">
      <div class="meta-row">
        <div class="publisher">{escape(article.publisher)}</div>
        <span class="meta-divider">·</span>
        <div class="status-inline">
          <span class="unread-label">안읽음</span>
          <span class="read-label">읽음</span>
          <span class="important-label">중요</span>
        </div>
        {_related_coverage_html(article)}
        <button class="important-button" type="button" aria-label="중요 기사로 표시">중요</button>
      </div>
      <div class="headline">{new_badge}{escape(article.title)}</div>
      {snippet_html}
    </div>
  </div>
  <div class="card-side">
    <div class="preview-image">{image_html}</div>
  </div>
</article>
"""

def render_group(group: str, articles: list[Article]) -> str:
    if not articles:
        return ""

    cards = "".join(
        render_card(article, index)
        for index, article in enumerate(articles, start=1)
    )

    return f'''
<section class="news-group">
  <div class="group-title">{escape(group)}</div>
  <div class="article-stack">{cards}</div>
</section>
'''



