    ("두산에너빌리티", ("두산에너빌리티", "doosan enerbility")),
    ("삼성물산", ("삼성물산", "samsung c&t")),
    ("대우건설", ("대우건설", "daewoo e&c")),
    ("현대엔지니어링", ("현대엔지니어링", "hyundai engineering")),
    ("DL이앤씨", ("dl이앤씨", "dl e&c")),
    ("GS건설", ("gs건설", "gs e&c")),
    ("SK에코플랜트", ("sk에코플랜트", "sk ecoplant")),
