def _title_country_mentions(title: str) -> list[tuple[int, str, str]]:
    """
    제목에 나타난 국가 표현을 등장 위치 순으로 반환합니다.
    (위치, 국가코드, 실제 매칭 표현)
    """
    lowered = title.lower()
    hits: list[tuple[int, str, str]] = []

    for code, markers in NUCLEAR_TITLE_COUNTRY_MARKERS:
        best_pos = None
        best_marker = None
        for marker in markers:
            if not _title_has_marker(title, marker):
                continue

            if len(marker) == 1 and marker in "美英中日佛韓":
                pos = title.find(marker)
            else:
                pos = lowered.find(marker.lower())

            if pos >= 0 and (best_pos is None or pos < best_pos):
                best_pos = pos
                best_marker = marker

        if best_pos is not None:
            hits.append((best_pos, code, best_marker or ""))

    return sorted(hits, key=lambda x: x[0])


def detect_nuclear_tab_primary_country(article: Article) -> str:
    """
    '원자력' 탭 전용 대표국가 판정.

    일반 지도용 국가 판정과 달리 제목에서 실제 기사 행위 주체를 우선합니다.
    특히 美/英/中/日/佛/韓 같은 제목용 한자 국가표기를 인식합니다.

    예:
      - 한국원자력연구원장 ... -> KR
      - 中 따라 잡겠다며 ... 카드 꺼낸 美 -> US
      - 베트남 국회 첫 원전사업 승인 ... -> VN
      - 美·英 손잡고 ... 中 조선패권 겨냥 -> US
    """
    title = html.unescape(article.title or "").strip()
    compact = re.sub(r"\s+", "", title)
    lowered = title.lower()
    mentions = _title_country_mentions(title)

    if not mentions:
        return detect_article_country(article)

    codes = [code for _, code, _ in mentions]

    # 1) 국가 정부/국회/규제기관이 명확히 제목의 사건 주체인 경우
    subject_patterns = (
        ("VN", ("베트남국회", "베트남정부", "vietnamnationalassembly", "vietnamesegovernment")),
        ("US", ("미국정부", "미정부", "미하원", "미상원", "미에너지부", "미원자력규제위원회")),
        ("KR", ("한국정부", "대한민국정부", "한국국회", "원자력안전위원회", "원안위")),
        ("GB", ("영국정부", "영국의회")),
        ("JP", ("일본정부", "일본의회")),
        ("CN", ("중국정부", "중국국무원")),
    )
    for code, patterns in subject_patterns:
        if any(p.replace(" ", "").lower() in compact.lower() for p in patterns):
            return code

    # 2) 명확한 국내기관이 핵심 주체인 제목
    korean_core_entities = (
        "한국원자력연구원", "한국수력원자력", "한수원",
        "한국전력", "원자력안전위원회", "원안위",
        "한국원자력환경공단", "한국원자력연료", "한전원자력연료",
    )
    if any(entity in title for entity in korean_core_entities):
        return "KR"

    # 3) 'A 따라잡겠다며 ... B가/美가 카드 꺼내' 구조:
    # 앞 국가는 비교대상이고 뒤 국가가 실제 행위 주체.
    rivalry_terms = (
        "따라잡", "견제", "겨냥", "맞서", "대항", "추격",
        "패권", "경쟁", "압박", "counter", "rival", "challenge",
    )
    action_terms = (
        "꺼낸", "꺼내", "개발", "추진", "나선", "나서", "발표",
        "승인", "도입", "투자", "건설", "계획", "협력", "손잡",
    )

    if len(mentions) >= 2:
        first_pos, first_code, _ = mentions[0]
        last_pos, last_code, _ = mentions[-1]

        # 제목 후반 국가가 행동의 주체이고, 전반 국가는 비교/견제 대상인 문장
        tail = compact[last_pos:].lower() if last_pos < len(compact) else compact.lower()
        if (
            any(term in compact.lower() for term in rivalry_terms)
            and any(term in compact.lower() for term in action_terms)
            and first_code != last_code
        ):
            # "美·英 손잡고 ... 中 겨냥"처럼 첫 두 국가가 공동주체인 경우는 첫 국가 유지
            first_two_prefix = re.match(r"^\s*[美英中日佛韓]\s*[·ㆍ&\-]\s*[美英中日佛韓]", title)
            if first_two_prefix:
                return mentions[0][1]

            # "... 中 ... 카드 꺼낸 美"처럼 행동 주체가 뒤에 오는 경우
            if any(x in compact for x in ("꺼낸美", "꺼내든美", "나선美", "추진하는美", "개발나선美")):
                return "US"
            if any(x in compact for x in ("꺼낸英", "나선英")):
                return "GB"
            if any(x in compact for x in ("꺼낸中", "나선中")):
                return "CN"
            if any(x in compact for x in ("꺼낸日", "나선日")):
                return "JP"

    # 4) 공동주체가 제목 맨 앞에 '美·英', '韓·美'처럼 나오면 첫 국가를 대표국가로 사용
    joint_prefix = re.match(r"^\s*([美英中日佛韓])\s*[·ㆍ&\-]\s*([美英中日佛韓])", title)
    if joint_prefix:
        han_to_code = {
            "美": "US", "英": "GB", "中": "CN",
            "日": "JP", "佛": "FR", "韓": "KR",
        }
        return han_to_code.get(joint_prefix.group(1), mentions[0][1])

    # 5) '베트남 국회 첫 원전사업 승인. 韓 ... 러시아·중국 ...'처럼
    # 첫 국가가 사건의 장소/주체로 명확하면 첫 제목 국가를 대표국가로 사용.
    first_pos, first_code, _ = mentions[0]
    if first_pos <= max(8, int(len(title) * 0.25)):
        return first_code

    # 6) 그 외에는 기존 국가 판정 결과를 우선하되, OTHER면 제목 첫 국가 사용
    detected = detect_article_country(article)
    if detected != "OTHER":
        return detected

    return mentions[0][1]


def _nuclear_article_importance_rank(article: Article) -> int:
    """
    원자력 탭의 같은 국가 내 기사 중요도.
    0: 핵심 정책·인허가·수주·계약·착공·대형원전/SMR 프로젝트
    1: 주요 기술·협력·운영·안전·연료/폐기물 이슈
    2: 일반 원자력 기사
    3: 주가·증권성 기사
    """
    if is_stock_market_low_priority_article(article):
        return 3

    title = html.unescape(article.title or "").lower()
    summary = html.unescape(getattr(article, "summary", None) or getattr(article, "snippet", None) or getattr(article, "description", None) or "").lower()
    blob = f"{title} {summary}"

    top_priority_terms = (
        "정책", "정부 발표", "정부", "법안", "입법", "규제", "규제당국",
        "승인", "허가", "인허가", "license", "licensing", "approval",
        "permit", "regulation", "regulatory", "government", "policy",
        "프로젝트", "project", "수주", "계약", "contract", "협약", "mou",
        "착공", "first concrete", "construction start", "준공", "상업운전",
        "commercial operation", "cod", "투자", "investment", "funding",
        "financing", "선정", "selected", "award", "awarded",
        "대형원전", "대형 원전", "nuclear power plant", "nuclear plant",
        "smr", "small modular reactor", "advanced reactor", "차세대 원자로",
        "신규 원전", "new nuclear", "원전 건설",
    )

    medium_priority_terms = (
        "원자로", "reactor",
        "핵연료", "nuclear fuel", "우라늄", "uranium",
        "사용후핵연료", "spent fuel", "방사성폐기물", "radioactive waste",
        "공급망", "supply chain",
        "협력", "cooperation", "파트너십", "partnership",
        "기술", "technology", "실증", "demonstration",
        "운영", "operation", "정비", "maintenance",
        "안전", "safety", "보안", "security",
        "해체", "decommissioning", "연구", "research", "개발", "development",
        "계속운전", "life extension", "재가동", "restart",
    )

    if any(term in blob for term in top_priority_terms):
        return 0
    if any(term in blob for term in medium_priority_terms):
        return 1
    return 2


def _nuclear_country_sort_key(article: Article) -> tuple[int, str, int, float]:
    """
    원자력 탭:
    국가별로 묶은 뒤, 같은 국가 안에서는 중요도순,
    같은 중요도 안에서는 최신순으로 배치합니다.
    """
    country = detect_nuclear_tab_primary_country(article)
    rank = NUCLEAR_COUNTRY_SORT_RANK.get(
        country,
        len(NUCLEAR_COUNTRY_SORT_ORDER) + 100,
    )
    return (
        rank,
        country,
        _nuclear_article_importance_rank(article),
        -article.published.timestamp(),
    )




STOCK_MARKET_LOW_PRIORITY_TERMS = (
    "주가", "급등", "급락", "강세", "약세", "상승세", "하락세",
    "상한가", "하한가", "증권사", "목표주가", "투자의견",
    "매수 의견", "매도의견", "리포트", "코스피", "코스닥",
    "stock", "shares", "share price", "rally", "surge", "soar",
    "plunge", "slump", "brokerage", "target price",
)


def is_stock_market_low_priority_article(article: Article) -> bool:
    """
    주가/증권성 기사라고 삭제하지 않습니다.
    해당 회사·원전·건설 기사로 분류된 상태는 그대로 유지하되
    각 기사탭의 뒤쪽에 배치하기 위한 정렬 플래그만 반환합니다.
    """
    hay = html.unescape(
        f"{article.title or ''} {article.description or ''}"
    ).lower()
    return any(term in hay for term in STOCK_MARKET_LOW_PRIORITY_TERMS)


def render_group_unified(
    group: str,
    articles: list[Article],
    new_urls: set[str] | None = None,
) -> str:
    new_urls = new_urls or set()

    korean_articles = [item for item in articles if item.language == 'ko']
    english_articles = [item for item in articles if item.language == 'en']

    def order_articles(items: list[Article]) -> list[Article]:
        if not items:
            return []

        # 원자력 탭은 국가별로 묶고, 같은 국가 안에서는 최신순으로 정렬
        if group == "원자력":
            return sorted(items, key=_nuclear_country_sort_key)

        # Holtec 공식 게시물은 실제 발행일 기준 최신순을 최우선으로 유지합니다.
        if group == "Holtec":
            return sorted(
                items,
                key=lambda item: -item.published.timestamp(),
            )

        # 주요 건설사 탭은 기사 제목에 나온 건설사 기준으로 묶고, 회사 내부는 최신순으로 정렬
        if group == "타 건설사":
            return sorted(
                items,
                key=lambda item: (
                    _other_construction_company_rank(item)[0],
                    1 if is_stock_market_low_priority_article(item) else 0,
                    -item.published.timestamp(),
                ),
            )

        buckets: dict[int, list[Article]] = {0: [], 1: [], 2: []}
        for item in items:
            priority, _ = _group_article_priority(item, group)
            buckets.setdefault(priority, []).append(item)

        ordered: list[Article] = []
        for priority in (0, 1, 2):
            bucket = sorted(
                buckets.get(priority, []),
                key=lambda item: (
                    1 if is_stock_market_low_priority_article(item) else 0,
                    -item.published.timestamp(),
                ),
            )
            ordered.extend(bucket)
        return ordered

    if group in ("원자력", "타 건설사"):
        # 원자력: 국가별 그룹핑이 언어 분리 때문에 깨지지 않도록 전체 기사 통합 정렬
        # 주요 건설사: 포스코이앤씨/POSCO E&C처럼 한·영 표기가 달라도
        # 같은 회사 기사끼리 완전히 붙도록 전체 기사 통합 정렬
        ordered_articles = order_articles(korean_articles + english_articles)
    else:
        ordered_articles = (
            order_articles(korean_articles)
            + order_articles(english_articles)
        )

    cards = ''.join(
        render_card(
            article,
            index,
            article.link in new_urls,
        )
        for index, article in enumerate(ordered_articles, start=1)
    )

    if not cards:
        cards = '<div class="empty">해당 시간대에 수집된 기사가 없습니다.</div>'

    article_total = len(ordered_articles)

    source_path_html = ""

    if group == "원전 관계부처":
        display_group = "원전 관계부처(산업통상부·기후부·과기부)"
    elif group == "타 건설사":
        display_group = "주요 건설사"
    elif group == "SMR":
        display_group = "SMR (차세대 원자로 포함)"
    else:
        display_group = group

    return f"""
<section class="news-group group-tab-section" data-group="{escape(group)}">
  <button class="group-title" type="button" aria-expanded="true">
    <span class="group-arrow">▲</span>
    <span class="group-name">{escape(display_group)}</span>
    <span class="group-count">{article_total}건</span>
  </button>
  <div class="article-stack">{cards}</div>
</section>
"""


# ============================================================
# FINAL DUPLICATE CONTROL
# exact duplicate: same canonical URL OR same publisher + normalized title
# → 목록에서 완전 삭제
# ============================================================

DEDUP_ENABLED = True

# 언론사마다 띄어쓰기·표기가 다른 회사/주제를 같은 토큰으로 맞춤
_DEDUP_ALIAS_REPLACEMENTS = (
    ("hd현대건설기계", "hd건설기계"),
    ("현대건설기계", "hd건설기계"),
    ("hyundai construction equipment", "hd건설기계"),
    ("hd 현대 건설기계", "hd건설기계"),
    ("hd현대 건설기계", "hd건설기계"),
    ("북미 시장", "북미시장"),
    ("북미시장 공략", "북미시장공략"),
    ("미국 건설사", "미국건설사"),
    ("테라 파워", "테라파워"),
    ("terra power", "terrapower"),
    ("소형 모듈 원자로", "smr"),
    ("소형모듈원자로", "smr"),
    ("hyundai e&c", "현대건설"),
    ("hyundai engineering & construction", "현대건설"),
)

def _canonical_news_url(url: str) -> str:
    """Remove fragments and common tracking parameters for exact URL duplicate checks."""
    if not url:
        return ""
    try:
        parsed = urlparse(url.strip())
        query_pairs = parse_qsl(parsed.query, keep_blank_values=True)
        filtered = [
            (k, v) for k, v in query_pairs
            if k.lower() not in {
                "utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content",
                "gclid", "fbclid", "ref", "source", "output", "oc",
            }
        ]
        path = re.sub(r"/+$", "", parsed.path or "")
        host = (parsed.netloc or "").lower()
        if host.startswith("www."):
            host = host[4:]
        return urlunparse((
            (parsed.scheme or "https").lower(),
            host,
            path,
            "",
            urlencode(filtered, doseq=True),
            "",
        )).lower()
    except Exception:
        return url.strip().lower()

def _normalize_dedup_title(title: str) -> str:
    value = (title or "").lower()
    value = re.sub(r"\[[^\]]+\]|\([^)]+\)", " ", value)
    for source, target in _DEDUP_ALIAS_REPLACEMENTS:
        value = value.replace(source, target)
    value = re.sub(r"[^0-9a-z가-힣]+", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    return value

def _publisher_key(article: Article) -> str:
    return re.sub(r"\s+", "", (article.publisher or "").lower())

def _same_exact_article(a: Article, b: Article) -> bool:
    # Same canonical article URL always wins.
    au = _canonical_news_url(a.link or a.source_url)
    bu = _canonical_news_url(b.link or b.source_url)
    if au and bu and au == bu:
        return True

    # Same publisher + exactly same normalized title.
    at = _normalize_dedup_title(a.title)
    bt = _normalize_dedup_title(b.title)
    return bool(
        at and bt
        and at == bt
        and _publisher_key(a) == _publisher_key(b)
    )

def _article_rep_score(article: Article) -> tuple:
    """완전 중복 중 더 풍부한 미리보기/이미지를 가진 쪽을 남깁니다."""
    description_len = len((article.description or "").strip())
    image_bonus = 1 if (article.image or "").strip() else 0
    publisher_bonus = 1 if (article.publisher or "").strip() and article.publisher != "출처 미확인" else 0
    link_bonus = 1 if (article.link or "").strip() else 0
    return (
        description_len,
        image_bonus,
        publisher_bonus,
        link_bonus,
        -int(article.published.timestamp()) if article.published else 0,
    )


def _is_mokdong10_event(article: Article) -> bool:
    """목동10단지 관련 보도는 언론사가 달라도 동일 이슈로 간주합니다."""
    haystack = normalized(f"{article.title} {article.description}")
    compact = re.sub(r"\s+", "", haystack)
    return (
        "목동10단지" in compact
        or ("목동" in compact and "10단지" in compact)
    )



