def _thumbnail_filename(article: Article) -> str:
    """로컬 캐시된 썸네일의 파일명만 반환합니다."""
    image = (article.image or "").strip().replace("\\", "/")
    if not image.startswith("assets/thumbnails/"):
        return ""
    name = Path(image).name.lower()
    if not re.fullmatch(r"[0-9a-f]{24}\.(?:jpg|png|webp|gif)", name):
        return ""
    return name


_THUMBNAIL_FP_RUNTIME_CACHE: dict[str, dict] | None = None


def _thumbnail_fingerprint_store_cached() -> dict[str, dict]:
    global _THUMBNAIL_FP_RUNTIME_CACHE
    if _THUMBNAIL_FP_RUNTIME_CACHE is None:
        _THUMBNAIL_FP_RUNTIME_CACHE = _load_thumbnail_fingerprint_store()
    return _THUMBNAIL_FP_RUNTIME_CACHE


def _thumbnail_fingerprint(article: Article) -> dict:
    name = _thumbnail_filename(article)
    if not name:
        return {}

    store = _thumbnail_fingerprint_store_cached()
    record = store.get(name)
    if isinstance(record, dict) and record.get("sha256"):
        return record

    # 예전 캐시 이미지라 sidecar에 없을 경우 즉석 계산
    local_path = THUMBNAIL_DIR / name
    if not local_path.exists():
        return {}

    computed = _compute_thumbnail_fingerprint(local_path)
    if not computed:
        return {}

    store[name] = computed
    return computed


def _hex_hamming_distance(a: str, b: str) -> int | None:
    try:
        return (int(a, 16) ^ int(b, 16)).bit_count()
    except Exception:
        return None


def _thumbnail_event_stage(article: Article) -> str | None:
    """
    기사에 명확히 표현된 사건 단계를 반환합니다.
    서로 다른 단계가 둘 다 확인되면 같은 사진이어도 합치지 않습니다.
    """
    haystack = html.unescape(
        f"{article.title} {(article.description or '')[:260]}"
    ).lower()
    compact = re.sub(r"\s+", "", haystack)

    for stage, terms in _THUMBNAIL_EVENT_STAGES.items():
        for term in terms:
            lowered = term.lower()
            if lowered in haystack or lowered.replace(" ", "") in compact:
                return stage
    return None


def _thumbnail_event_tokens(article: Article) -> set[str]:
    """사진 중복 판정용 핵심 주체·대상·행위 토큰."""
    return {
        token
        for token in event_signature_tokens(article)
        if token not in _THUMBNAIL_DEDUP_GENERIC_TOKENS
        and len(token) >= 2
    }


def _same_thumbnail_content_context(a: Article, b: Article, *, exact_image: bool) -> bool:
    """
    사진이 같다는 사실만으로는 삭제하지 않고 기사 내용도 같이 확인합니다.

    확실한 중복으로 인정하는 경우:
    - 제목의 사건 개념(주체/대상/행위)이 동일하다고 기존 로직이 판정하거나
    - 핵심 토큰이 충분히 겹치고 제목 유사도도 일정 수준 이상인 경우

    exact_image=False(dHash 유사 사진)는 오탐 방지를 위해 더 엄격하게 봅니다.
    """
    title_a = a.title or ""
    title_b = b.title or ""

    # 기존의 보수적인 동일 사건/보도자료 판정 결과를 우선 활용
    if is_same_event(title_a, title_b) or same_press_release_event(title_a, title_b):
        return True

    tokens_a = _thumbnail_event_tokens(a)
    tokens_b = _thumbnail_event_tokens(b)
    if not tokens_a or not tokens_b:
        return False

    common = tokens_a & tokens_b
    containment = len(common) / max(1, min(len(tokens_a), len(tokens_b)))
    title_similarity = semantic_duplicate_score(title_a, title_b)

    # 파일 자체가 완전히 같은 이미지: 핵심어 3개 이상 + 충분한 내용 겹침
    if exact_image:
        if len(common) >= 4:
            return True
        if len(common) >= 3 and containment >= 0.50 and title_similarity >= 0.45:
            return True
        return False

    # perceptual hash가 가까운 경우:
    # 사진이 실제로 매우 유사하고, 핵심 주체·대상·행위가 3개 이상 겹치면 동일 보도로 인정.
    # 사건 단계가 다른 경우는 상위 함수에서 이미 제외됩니다.
    if len(common) >= 4 and containment >= 0.50 and title_similarity >= 0.45:
        return True
    if len(common) >= 3 and containment >= 0.55 and title_similarity >= 0.50:
        return True

    return False


def _same_thumbnail_same_event(a: Article, b: Article) -> bool:
    """
    '확실한 중복기사'만 대표 1건으로 묶습니다.

    필수 조건
    1) 서로 다른 언론사
    2) 실제 썸네일이 완전히 동일(SHA-256) 또는 매우 유사(dHash/aHash)
    3) 제목/미리보기의 핵심 주체·대상·행위가 같은 사건
    4) 둘 다 사건 단계가 명시됐는데 단계가 다르면 절대 병합하지 않음

    따라서 같은 회사가 같은 대표사진을 다른 기사에 재사용하는 경우는
    사진만 같다는 이유로 중복 처리하지 않습니다.
    """
    publisher_a = (a.publisher or "").strip()
    publisher_b = (b.publisher or "").strip()
    if not publisher_a or not publisher_b or publisher_a == publisher_b:
        return False

    # 명확히 다른 사건 단계는 보호: MOU ≠ 본계약 ≠ 착공 ≠ 준공 등
    stage_a = _thumbnail_event_stage(a)
    stage_b = _thumbnail_event_stage(b)
    if stage_a and stage_b and stage_a != stage_b:
        return False

    fp_a = _thumbnail_fingerprint(a)
    fp_b = _thumbnail_fingerprint(b)
    if not fp_a or not fp_b:
        return False

    sha_a = str(fp_a.get("sha256") or "")
    sha_b = str(fp_b.get("sha256") or "")
    exact_image = bool(sha_a and sha_b and sha_a == sha_b)

    near_image = False
    if not exact_image:
        dhash_a = str(fp_a.get("dhash") or "")
        dhash_b = str(fp_b.get("dhash") or "")
        ahash_a = str(fp_a.get("ahash") or "")
        ahash_b = str(fp_b.get("ahash") or "")

        d_distance = _hex_hamming_distance(dhash_a, dhash_b) if dhash_a and dhash_b else None
        a_distance = _hex_hamming_distance(ahash_a, ahash_b) if ahash_a and ahash_b else None

        # 같은 원본을 언론사별로 리사이즈/재압축한 정도는 허용.
        # 사진만으로 삭제하지 않고 아래의 기사 내용/사건 단계 검증을 반드시 통과해야 합니다.
        near_image = (
            (d_distance is not None and d_distance <= THUMBNAIL_DHASH_MAX_DISTANCE)
            or (a_distance is not None and a_distance <= 5)
            or (
                d_distance is not None and a_distance is not None
                and d_distance <= 9 and a_distance <= 8
            )
        )

    if not (exact_image or near_image):
        return False

    return _same_thumbnail_content_context(
        a,
        b,
        exact_image=exact_image,
    )

def _deduplicate_identical_thumbnail_events(
    articles: list[Article],
) -> tuple[list[Article], int]:
    """
    서로 다른 언론사가 동일/거의 동일한 썸네일을 쓰면서
    핵심 주체·대상·행위까지 같은 확실한 동일 사건일 때만 대표기사 1건을 유지합니다.
    """
    result: list[Article] = []
    removed = 0

    for article in sorted(articles, key=lambda x: x.published, reverse=True):
        if not _thumbnail_filename(article):
            result.append(article)
            continue

        matched_idx = None
        for idx, kept in enumerate(result):
            if _same_thumbnail_same_event(article, kept):
                matched_idx = idx
                break

        if matched_idx is None:
            result.append(article)
            continue

        removed += 1
        if _article_rep_score(article) > _article_rep_score(result[matched_idx]):
            result[matched_idx] = article

    return sorted(result, key=lambda x: x.published, reverse=True), removed


CONSTRUCTION_UNION_TERMS = (
    "노조",
    "노동조합",
    "건설노조",
    "건설사노조",
    "건설사 노조",
    "labor union",
    "trade union",
    "union",
)

def _construction_union_event_key(article: Article) -> tuple[str, str] | None:
    """
    같은 날짜에 올라온 같은 건설사의 노조 관련 보도는 동일 이슈로 묶습니다.
    서로 다른 건설사의 노조 기사는 합치지 않습니다.
    """
    haystack = html.unescape(f"{article.title} {article.description}").lower()
    compact = re.sub(r"\s+", "", haystack)

    has_union = any(
        term in haystack or term.replace(" ", "") in compact
        for term in CONSTRUCTION_UNION_TERMS
    )
    if not has_union:
        return None

    company = None
    for canonical, aliases in CONSTRUCTION_UNION_COMPANY_ALIASES.items():
        if any(
            alias.lower() in haystack or alias.lower().replace(" ", "") in compact
            for alias in aliases
        ):
            company = canonical
            break

    if not company:
        return None

    date_key = article.published.astimezone(KST).strftime("%Y-%m-%d")
    return date_key, company


